function formatMoney(value: string | null | undefined) {
  if (!value) return "Não informado";
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value));
}

function formatDate(value: Date | string | null | undefined) {
  if (!value) return "—";
  return new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium", timeStyle: value instanceof Date ? "short" : undefined }).format(new Date(value));
}

const friendlyRole = presentationRole;
const friendlyStatus = presentationStatus;
const friendlyInternalLabel = presentationLabel;

function Status({ tone = "neutral", children }: { tone?: StatusTone; children: ReactNode }) {
  const content = typeof children === "string" && /^(active|draft|blocked|suspended|authorized|contracted|archived|annulled|revoked|cancelled|in_progress|completed|waiting|returned|skipped|pending|submitted|under_review|accepted|rejected|grouped|awaiting_pca_publication|published_in_pca|awaiting_opening|opening_authorized|process_instantiated|instantiated|consolidating|presidency_review|approved_for_publication|published|open|acknowledged|resolved|awaiting_credentials|ready_for_authorization|authorization_requested|signed|failed|pending_review|restricted|inactive|unknown|low|medium|high|approved|needs_changes|risk_accepted|not_applicable|selected|received)$/.test(children) ? friendlyStatus(children).text : children;
  return <span className={`status status-${tone}`}><i />{content}</span>;
}

function PcaDocumentActions({ pca }: { pca: { publicId: string; status: string; documentUrl?: string | null } }) {
  const utils = trpc.useUtils();
  const generate = trpc.planning.generatePcaArtifact.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const canGenerate = ["draft", "returned"].includes(pca.status);
  return <div className="inline-actions">
    {canGenerate && <button className="button button-outline button-sm" type="button" disabled={generate.isPending} onClick={() => generate.mutate({ pcaPublicId: pca.publicId })}><FileText size={14} />{generate.isPending ? "Gerando…" : "Gerar documento PCA"}</button>}
    {pca.documentUrl && <a className="button button-ghost button-sm" href={pca.documentUrl} target="_blank" rel="noreferrer"><FileCheck2 size={14} /> Ver documento</a>}
    {generate.error && <small className="form-error">{generate.error.message}</small>}
  </div>;
}

function PcaUpdateActions({ update }: { update: { publicId: string; status: string; documentUrl?: string | null; publicationReference?: string | null; updateNumber: number; title: string; demandDetails: { publicId: string; title: string }[] } }) {
  const utils = trpc.useUtils();
  const generate = trpc.planning.generatePcaUpdateArtifact.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const submit = trpc.planning.submitPcaUpdate.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const decide = trpc.planning.decidePcaUpdate.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const publish = trpc.planning.publishPcaUpdate.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const [confirmationOpen, setConfirmationOpen] = useState(false);
  const [publicationReference, setPublicationReference] = useState("");
  const [confirmationError, setConfirmationError] = useState<string | null>(null);
  const decision = (action: "approve" | "return" | "reject") => { const notes = window.prompt(action === "approve" ? "Registre a motivação da autorização da atualização:" : "Registre a motivação da decisão:"); if (notes?.trim()) decide.mutate({ pcaUpdatePublicId: update.publicId, action, notes: notes.trim() }); };
  const confirmPublication = (event: { preventDefault: () => void }) => {
    const referenceError = publicationReferenceError(publicationReference);
    if (referenceError) { event.preventDefault(); setConfirmationError(referenceError); return; }
    publish.mutate({ pcaUpdatePublicId: update.publicId, publicationReference: publicationReference.trim() }, { onSuccess: () => { setConfirmationOpen(false); setPublicationReference(""); setConfirmationError(null); } });
  };
  const label = update.status === "draft" ? "Aguardando documento" : update.status === "ready_for_review" ? "Pronta para encaminhar" : update.status === "presidency_review" ? "Aguardando Presidência" : update.status === "approved_for_publication" ? "Autorizada para publicação" : update.status === "published" ? "Publicada" : update.status === "returned" ? "Devolvida para ajuste" : update.status === "rejected" ? "Não aprovada" : presentationStatus(update.status).text;
  return <><div className="checklist-row"><span className="check-circle"><FileText size={14} /></span><div><strong>Atualização {update.updateNumber}</strong><small>{update.publicId} · {label}</small></div><div className="tag-row">{["draft", "returned"].includes(update.status) ? <button className="text-button" type="button" disabled={generate.isPending} onClick={() => generate.mutate({ pcaUpdatePublicId: update.publicId })}>Gerar documento revisado</button> : null}{update.documentUrl ? <a className="text-button" href={update.documentUrl} target="_blank" rel="noreferrer">Ver documento</a> : null}{["ready_for_review", "returned"].includes(update.status) ? <button className="text-button" type="button" disabled={submit.isPending} onClick={() => submit.mutate({ pcaUpdatePublicId: update.publicId })}>Enviar à Presidência</button> : null}{update.status === "presidency_review" ? <><button className="text-button" type="button" onClick={() => decision("approve")}>Autorizar</button><button className="text-button" type="button" onClick={() => decision("return")}>Devolver</button><button className="text-button" type="button" onClick={() => decision("reject")}>Rejeitar</button></> : null}{update.status === "approved_for_publication" ? <button className="text-button" type="button" onClick={() => setConfirmationOpen(true)}>Revisar antes de publicar</button> : null}{update.status === "published" ? <Status tone="success">Publicada</Status> : null}</div></div><AlertDialog open={confirmationOpen} onOpenChange={setConfirmationOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Confirmar publicação da atualização</AlertDialogTitle><AlertDialogDescription>Revise o impacto abaixo antes de tornar a atualização efetiva. As DFDs incluídas serão disponibilizadas ao Setor de Compras após a confirmação.</AlertDialogDescription></AlertDialogHeader><div className="confirmation-summary"><p><strong>Atualização:</strong> {update.publicId} · versão {update.updateNumber}</p><p><strong>Documento revisado:</strong> {update.title}</p><p><strong>DFDs adicionadas:</strong> {update.demandDetails.length}</p><ul>{update.demandDetails.map(demand => <li key={demand.publicId}>{demand.publicId} · {demand.title}</li>)}</ul><label className="field-label" htmlFor={`publication-reference-${update.publicId}`}>Referência, URL ou comprovante da publicação</label><input id={`publication-reference-${update.publicId}`} value={publicationReference} onChange={event => { setPublicationReference(event.target.value); setConfirmationError(null); }} placeholder="Ex.: Diário Oficial nº 123, de 18/08/2026" autoFocus />{confirmationError ? <p className="form-error">{confirmationError}</p> : null}{publish.error ? <p className="form-error">{publish.error.message}</p> : null}</div><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction disabled={publish.isPending} onClick={confirmPublication}>{publish.isPending ? "Publicando…" : "Confirmar publicação"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

function AnnualPcaDirectDemandPanel() {
  const utils = trpc.useUtils();
  const board = trpc.planning.board.useQuery();
  const [selectedDemandIds, setSelectedDemandIds] = useState<string[]>([]);
  const [originFilter, setOriginFilter] = useState<"all" | "isolated" | "consolidated">("isolated");
  const [searchQuery, setSearchQuery] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const createPca = trpc.planning.createPca.useMutation({ onSuccess: () => { setSelectedDemandIds([]); setFormError(null); utils.planning.board.invalidate(); } });
  const createUpdate = trpc.planning.createPcaUpdate.useMutation({ onSuccess: () => { setSelectedDemandIds([]); setFormError(null); utils.planning.board.invalidate(); } });
  const consolidationDemandIds = new Set((board.data?.demandConsolidations ?? []).flatMap(group => group.demandDetails.map(demand => demand.publicId)));
  const demandRows = uniqueAgendaRows((board.data?.demands ?? []).map(row => ({ ...row, id: row.demand.id, isConsolidated: consolidationDemandIds.has(row.demand.publicId) }))).filter(row => ["submitted", "under_review", "accepted", "returned", "grouped"].includes(row.demand.status));
  const demands = filterDemandRowsByOrigin(demandRows, originFilter).filter(row => matchesDfdSearch(row.demand, searchQuery));
  const originCounts = demandOriginCounts(demandRows);
  const plans = uniqueAgendaRows(board.data?.plans ?? []);
  const toggle = (publicId: string) => setSelectedDemandIds(current => current.includes(publicId) ? current.filter(item => item !== publicId) : [...current, publicId]);
  const exportFilteredDemands = () => {
    const csv = buildDfdCsv(demands.map(row => ({ publicId: row.demand.publicId, title: row.demand.title, unitName: row.unitName, estimatedValue: row.demand.initialEstimatedValue, origin: row.isConsolidated ? "Já consolidada" : "DFD isolada", status: friendlyStatus(row.demand.status).text })));
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `dfds-${originFilter === "all" ? "todas" : originFilter === "isolated" ? "isoladas" : "consolidadas"}.csv`;
    anchor.click();
    URL.revokeObjectURL(url);
  };
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const planId = Number(data.get("planId"));
    const title = String(data.get("title") ?? "").trim();
    if (!planId || !selectedDemandIds.length) { setFormError("Selecione o exercício anual e ao menos uma DFD isolada."); return; }
    const existingPca = (board.data?.pcas ?? []).find(pca => pca.planId === planId);
    if (existingPca?.status === "published") { createUpdate.mutate({ pcaPublicId: existingPca.publicId, title: title || undefined, demandPublicIds: selectedDemandIds }); return; }
    if (existingPca) { setFormError("Este exercício já possui um PCA em elaboração. Conclua a composição, o documento e a deliberação antes de uma nova atualização."); return; }
    createPca.mutate({ title, planId, demandConsolidationPublicIds: [], demandPublicIds: selectedDemandIds });
  };
  return <section className="surface-panel">
    <div className="panel-heading"><div><span className="panel-kicker">PCA ANUAL / DFD ISOLADAS E ATUALIZAÇÕES</span><h2>Inserir DFD diretamente no PCA</h2></div><CalendarDays size={20} /></div>
    <p className="trilha-current-copy">DFDs sem necessidade de consolidação prévia podem compor diretamente o PCA anual. Se o PCA do exercício já estiver publicado, a inclusão abre uma atualização com documento revisado, deliberação da Presidência e publicação da alteração.</p>
    {board.isLoading ? <LoadingPanel message="Carregando DFDs disponíveis…" /> : <form className="form-stack" onSubmit={submit}>
      <Field label="Exercício anual"><select name="planId" required defaultValue=""><option value="" disabled>Selecione o exercício do PCA</option>{plans.map(plan => <option key={plan.id} value={plan.id}>{plan.fiscalYear} · {plan.title}</option>)}</select></Field>
      <Field label="Título do PCA ou da atualização" full><input name="title" required minLength={5} placeholder="Ex.: PCA anual 2027 — atualização de setembro" /></Field>
      <div className="filter-row" role="group" aria-label="Filtrar DFDs por origem">
        <button className={`text-button ${originFilter === "all" ? "is-active" : ""}`} type="button" onClick={() => setOriginFilter("all")}>Todas ({originCounts.all})</button>
        <button className={`text-button ${originFilter === "isolated" ? "is-active" : ""}`} type="button" onClick={() => setOriginFilter("isolated")}>Isoladas ({originCounts.isolated})</button>
        <button className={`text-button ${originFilter === "consolidated" ? "is-active" : ""}`} type="button" onClick={() => setOriginFilter("consolidated")}>Já consolidadas ({originCounts.consolidated})</button>
      </div>
      <div className="dfd-list-tools"><label className="dfd-search"><Search size={15} /><input value={searchQuery} onChange={event => setSearchQuery(event.target.value)} placeholder="Buscar por título ou número da DFD" aria-label="Buscar por título ou número da DFD" /></label><button className="button button-ghost button-sm" type="button" onClick={exportFilteredDemands} disabled={!demands.length}><Download size={14} /> Exportar CSV ({demands.length})</button></div>
      <div className="checklist-box">{demands.length ? demands.map(row => <label className="checklist-row" key={row.id}>
        <input type="checkbox" disabled={row.isConsolidated} checked={selectedDemandIds.includes(row.demand.publicId)} onChange={() => toggle(row.demand.publicId)} />
        <div><strong>{row.demand.title}{row.demand.isSupervening ? <span className="supervening-badge"><AlertTriangle size={12} aria-hidden="true" /> Superveniente</span> : null}</strong><small>{row.demand.publicId} · {row.unitName} · {formatMoney(row.demand.initialEstimatedValue)}</small></div>
        <Status tone={row.isConsolidated ? "neutral" : "info"}>{row.isConsolidated ? "Já passou por consolidação" : "DFD isolada"}</Status>
      </label>) : <p className="task-empty">Não há DFD correspondente aos filtros e à busca informados.</p>}</div>
      {originFilter === "consolidated" ? <p className="task-empty">DFDs já consolidadas são incluídas no PCA por meio da respectiva consolidação; por isso não podem ser selecionadas diretamente aqui.</p> : null}
      <p className="task-empty">{selectedDemandIds.length} DFD(s) selecionada(s). A publicação nunca é automática.</p>
      {formError || createPca.error || createUpdate.error ? <p className="form-error">{formError ?? createPca.error?.message ?? createUpdate.error?.message}</p> : null}
      <button className="button button-ink button-sm" type="submit" disabled={!plans.length || !selectedDemandIds.length || createPca.isPending || createUpdate.isPending}>{createPca.isPending || createUpdate.isPending ? "Registrando…" : "Incluir no PCA anual"} <ArrowRight size={15} /></button>
    </form>}
  </section>;
}

function PlanningChecklistPanel({ items }: { items: { id: number; entityType: "demand" | "demand_consolidation" | "pca" | "consolidation" | "opening_request"; entityPublicId: string; title: string; status: string; required: boolean; notes?: string | null }[] }) {
  const utils = trpc.useUtils();
  const update = trpc.planning.completeChecklist.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const entityLabel = (entityType: string) => entityType === "demand" ? "DFD" : entityType === "demand_consolidation" ? "Consolidação de demandas" : entityType === "pca" || entityType === "consolidation" ? "PCA" : "Abertura";
  const waive = (itemId: number) => { const notes = window.prompt("Registre a justificativa institucional para dispensar este item:"); if (notes?.trim()) update.mutate({ itemId, status: "waived", notes: notes.trim() }); };
  return <section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">OFICINA / CONTROLES</span><h2>Checklists de planejamento</h2></div><ListChecks size={20} /></div><p className="trilha-current-copy">Itens aplicados a partir dos modelos ativos do OFICINA. A dispensa exige justificativa e todas as ações ficam registradas na auditoria.</p>{items.length ? <div className="checklist-box">{items.map(item => <div className="checklist-row" key={item.id}><span className="check-circle">{item.status === "completed" ? <Check size={14} /> : <ListChecks size={14} />}</span><div><strong>{item.title}</strong><small>{entityLabel(item.entityType)} · {item.entityPublicId}{item.required ? " · Obrigatório" : ""}{item.notes ? ` · ${item.notes}` : ""}</small></div><div className="tag-row">{item.status === "pending" ? <><button className="text-button" type="button" disabled={update.isPending} onClick={() => update.mutate({ itemId: item.id, status: "completed" })}>Concluir</button><button className="text-button" type="button" disabled={update.isPending} onClick={() => waive(item.id)}>Dispensar</button></> : <Status tone={item.status === "completed" ? "success" : "warning"}>{item.status === "completed" ? "Concluído" : "Dispensado"}</Status>}</div></div>)}</div> : <p className="task-empty">Não há itens de checklist aplicados. No OFICINA, crie e ative modelos destinados à DFD, ao PCA ou à solicitação de abertura.</p>}{update.error && <p className="form-error">{update.error.message}</p>}</section>;
}

function PlanningDeadlineAlerts({ alerts }: { alerts: { id: number; entityType: "demand" | "demand_consolidation" | "pca" | "consolidation" | "opening_request"; entityPublicId: string; severity: "info" | "warning" | "critical"; title: string; dueAt?: Date | null; status: "open" | "acknowledged" | "resolved" }[] }) {
  const utils = trpc.useUtils();
  const acknowledge = trpc.planning.acknowledgeAlert.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const refresh = trpc.planning.refreshDeadlines.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const kind = (entityType: string) => entityType === "demand" ? "DFD" : entityType === "demand_consolidation" ? "Consolidação de demandas" : entityType === "pca" || entityType === "consolidation" ? "PCA" : "Abertura";
  return <section className="surface-panel alert-panel"><div className="panel-heading"><div><span className="panel-kicker">FAROL / PRAZOS</span><h2>Alertas acionáveis</h2></div><button className="text-button" type="button" disabled={refresh.isPending} onClick={() => refresh.mutate()}>{refresh.isPending ? "Atualizando…" : "Atualizar prazos"}</button></div>{alerts.length ? <div className="checklist-box">{alerts.map(alert => <div className="checklist-row" key={alert.id}><span className="check-circle"><Bell size={14} /></span><div><strong>{alert.title}</strong><small>{kind(alert.entityType)} · {alert.entityPublicId}{alert.dueAt ? ` · vence ${formatDate(alert.dueAt)}` : " · sem prazo definido"}</small></div><div className="tag-row"><Status tone={alert.severity === "critical" ? "danger" : alert.severity === "warning" ? "warning" : "info"}>{alert.severity === "critical" ? "Em atraso" : "Em acompanhamento"}</Status>{alert.status === "open" ? <button className="text-button" type="button" disabled={acknowledge.isPending} onClick={() => acknowledge.mutate({ alertId: alert.id })}>Ciente</button> : <Status tone="neutral">Ciente</Status>}</div></div>)}</div> : <EmptyState icon={<ShieldCheck size={26} />} title="Nenhum alerta de planejamento" text="Os prazos de DFD, PCA e abertura aparecerão aqui quando aplicáveis." />}{acknowledge.error || refresh.error ? <p className="form-error">{acknowledge.error?.message ?? refresh.error?.message}</p> : null}</section>;
}

