function DemandControlDialog({ demandPublicId, open, onOpenChange, modalityItems, openProcess }: { demandPublicId: string; open: boolean; onOpenChange: (open: boolean) => void; modalityItems: { id: number; label: string }[]; openProcess: (publicId: string) => void }) {
  const utils = trpc.useUtils();
  const detail = trpc.planning.demandControl.useQuery({ demandPublicId }, { enabled: open });
  const [note, setNote] = useState("");
  const refresh = async () => {
    await Promise.all([utils.planning.demandControl.invalidate({ demandPublicId }), utils.planning.board.invalidate(), utils.dashboard.summary.invalidate(), utils.procurement.list.invalidate()]);
    setNote("");
  };
  const startAnalysis = trpc.planning.startDemandAnalysis.useMutation({ onSuccess: refresh });
  const requestComplementation = trpc.planning.requestDemandComplementation.useMutation({ onSuccess: refresh });
  const provideComplementation = trpc.planning.provideDemandComplementation.useMutation({ onSuccess: refresh });
  const approve = trpc.planning.approveDemand.useMutation({ onSuccess: refresh });
  const createOpening = trpc.planning.createOpeningRequest.useMutation({ onSuccess: refresh });
  const instantiate = trpc.planning.instantiateProcess.useMutation({ onSuccess: async result => { await refresh(); openProcess(result.publicId); } });
  const actionError = startAnalysis.error ?? requestComplementation.error ?? provideComplementation.error ?? approve.error ?? createOpening.error ?? instantiate.error;
  const eventLabel: Record<string, string> = { analysis_started: "Análise iniciada", complementation_requested: "Complementação solicitada", complementation_provided: "Complementação recebida", approved: "DFD aprovada", returned: "DFD devolvida" };
  const data = detail.data;
  const review = data ? demandReviewState(data.demand.status, data.events.map(item => ({ eventType: item.event.eventType, createdAt: item.event.createdAt }))) : null;
  const canActOnReview = data?.canReview && ["submitted", "under_review"].includes(data.demand.status);
  const canRequestOpening = data?.canOpen && data.demand.status === "published_in_pca" && !data.openingRequest;
  const canInstantiate = data?.canOpen && data.openingRequest?.status === "authorized";
  const submitOpening = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    createOpening.mutate({ demandPublicId, proposedWorkflowType: String(form.get("proposedWorkflowType")) as "direct_contracting" | "bidding", proposedModality: String(form.get("proposedModality") ?? ""), justification: String(form.get("justification") ?? "") });
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="demand-control-dialog"><DialogHeader><span className="panel-kicker">CONTROLE INDIVIDUAL DA DFD</span><DialogTitle>{data?.demand.title || "Carregando DFD"}</DialogTitle><DialogDescription>{data ? `${data.demand.publicId} · ${data.unitName} · solicitada por ${data.requesterName || "usuário institucional"}` : "Aguarde o carregamento dos dados."}</DialogDescription></DialogHeader>{detail.isLoading ? <LoadingPanel message="Carregando histórico e situação da DFD…" /> : detail.error ? <p className="form-error">{detail.error.message}</p> : data && review ? <div className="demand-control-content"><section className="demand-control-overview"><div><span className="panel-kicker">SITUAÇÃO DA ANÁLISE</span><Status tone={review.tone === "success" ? "success" : review.tone === "warning" ? "warning" : review.tone === "info" ? "info" : "neutral"}>{review.label}</Status></div><div><span className="panel-kicker">ETAPA INSTITUCIONAL</span><Status tone={data.demand.status === "process_instantiated" ? "success" : data.demand.status === "returned" ? "warning" : "info"}>{friendlyStatus(data.demand.status).text}</Status></div></section><section className="demand-detail-grid"><div><span>Objeto / descrição</span><strong>{data.demand.objectDescription}</strong></div><div><span>Justificativa da necessidade</span><strong>{data.demand.justification}</strong></div><div><span>Quantidade e unidade</span><strong>{data.demand.quantity ? `${data.demand.quantity} ${data.demand.unitOfMeasure || "unidade(s)"}` : "Não informada"}</strong></div><div><span>Estimativa inicial</span><strong>{formatMoney(data.demand.initialEstimatedValue)}</strong></div><div><span>Data desejada</span><strong>{formatDate(data.demand.desiredContractDate)}</strong></div><div><span>Prazo de entrega / execução</span><strong>{data.demand.deliveryPeriod || "Não informado"}</strong></div>{data.demand.isSupervening ? <div><span>Necessidade superveniente</span><strong>{data.demand.planningJustification || "Justificativa não informada"}</strong></div> : null}{data.demand.containsPersonalData || data.demand.containsSensitiveData ? <div><span>Triagem de privacidade</span><strong>{data.demand.containsSensitiveData ? "Possui dados pessoais sensíveis" : "Possui dados pessoais"}{data.demand.privacyContext ? ` · ${data.demand.privacyContext}` : ""}</strong></div> : null}</section><section className="demand-action-panel"><div><span className="panel-kicker">REGISTRO DA AÇÃO</span><h3>Análise e complementação</h3><p>Descreva objetivamente a análise, o ponto a complementar ou a motivação da aprovação. Cada registro fica visível na linha do tempo.</p><textarea value={note} onChange={event => setNote(event.target.value)} maxLength={5000} placeholder={data.canRespond && data.demand.status === "returned" ? "Descreva a complementação fornecida pelo setor requisitante." : "Registre a observação ou fundamentação da ação."} /></div><div className="demand-action-buttons">{canActOnReview ? <button className="button button-outline button-sm" type="button" disabled={startAnalysis.isPending} onClick={() => startAnalysis.mutate({ demandPublicId, note: note.trim() || undefined })}><Eye size={14} /> {startAnalysis.isPending ? "Registrando…" : "Marcar como analisada"}</button> : null}{canActOnReview ? <button className="button button-outline button-sm" type="button" disabled={requestComplementation.isPending || note.trim().length < 5} onClick={() => requestComplementation.mutate({ demandPublicId, note: note.trim() })}><FileCog size={14} /> {requestComplementation.isPending ? "Enviando…" : "Solicitar complementação"}</button> : null}{data.canApprove && canActOnReview ? <button className="button button-ink button-sm" type="button" disabled={approve.isPending || note.trim().length < 5} onClick={() => approve.mutate({ demandPublicId, note: note.trim() })}><Check size={14} /> {approve.isPending ? "Aprovando…" : "Aprovar DFD"}</button> : null}{data.canRespond && data.demand.status === "returned" ? <button className="button button-ink button-sm" type="button" disabled={provideComplementation.isPending || note.trim().length < 5} onClick={() => provideComplementation.mutate({ demandPublicId, note: note.trim() })}><Send size={14} /> {provideComplementation.isPending ? "Respondendo…" : "Enviar complementação"}</button> : null}</div></section><section className="demand-action-panel"><div><span className="panel-kicker">CONTRATAÇÃO VINCULADA</span><h3>Da DFD à instauração</h3>{data.process ? <p>Processo instaurado: <strong>{data.process.publicId}</strong> · {friendlyStatus(data.process.status).text}.</p> : data.openingRequest ? <p>Solicitação {data.openingRequest.publicId} · {friendlyStatus(data.openingRequest.status).text} · modalidade proposta: {data.openingRequest.proposedModality}.</p> : <p>A contratação será disponibilizada somente após a publicação do PCA que contém esta DFD.</p>}</div>{canRequestOpening ? <form className="form-stack compact-form" onSubmit={submitOpening}><Field label="Trilha proposta"><select name="proposedWorkflowType" defaultValue="direct_contracting"><option value="direct_contracting">Contratação direta</option><option value="bidding">Licitação</option></select></Field><Field label="Modalidade proposta"><select name="proposedModality" required defaultValue=""><option value="" disabled>Selecione a modalidade</option>{modalityItems.map(item => <option key={item.id} value={item.label}>{item.label}</option>)}</select></Field><Field label="Justificativa para abertura" full><textarea name="justification" required minLength={10} placeholder="Fundamente a abertura e a modalidade proposta." /></Field><button className="button button-ink button-sm" type="submit" disabled={createOpening.isPending}>{createOpening.isPending ? "Enviando…" : "Iniciar contratação"} <ArrowRight size={14} /></button></form> : null}{canInstantiate ? <button className="button button-ink button-sm" type="button" disabled={instantiate.isPending} onClick={() => instantiate.mutate({ requestPublicId: data.openingRequest!.publicId })}>{instantiate.isPending ? "Instaurando…" : "Instaurar processo"} <ArrowRight size={14} /></button> : null}{data.process ? <button className="button button-outline button-sm" type="button" onClick={() => openProcess(data.process!.publicId)}>Abrir processo na TRILHA <ArrowRight size={14} /></button> : null}</section><section className="demand-timeline"><div className="panel-heading"><div><span className="panel-kicker">HISTÓRICO AUDITÁVEL</span><h3>Leituras, análises e decisões</h3></div><Clock3 size={18} /></div>{data.events.length ? <ol>{data.events.map(item => <li key={item.event.id}><span className="timeline-dot" /><div><strong>{eventLabel[item.event.eventType] || item.event.eventType}</strong><small>{item.actorName || "Usuário institucional"} · {formatDate(item.event.createdAt)}</small>{item.event.note ? <p>{item.event.note}</p> : null}</div></li>)}</ol> : <p className="task-empty">Ainda não há análise registrada. Use “Marcar como analisada” para iniciar a trilha auditável.</p>}</section>{data.documents.length ? <section className="demand-documents"><span className="panel-kicker">DOCUMENTOS DA DFD</span>{data.documents.map(document => <a key={document.id} className="text-button" href={document.fileUrl} target="_blank" rel="noreferrer"><Paperclip size={14} /> {document.title}</a>)}</section> : null}{actionError ? <p className="form-error">{actionError.message}</p> : null}</div> : null}</DialogContent></Dialog>;
}

function FutureFiscalImpactReport({ demands }: { demands: { demand: { publicId: string; title: string; initialEstimatedValue: string | null; supplyLineCnaeCode: string | null; supplyLineCnaeDescription: string | null; status: string }; unitName: string }[] }) {
  return <section className="surface-panel future-fiscal-report"><div className="panel-heading"><div><span className="panel-kicker">RELATÓRIO FINANCEIRO</span><h2>DFDs com impacto em exercícios futuros</h2></div><Landmark size={20} /></div><p className="trilha-current-copy">Este recorte reúne as demandas que declaram gastos previstos para exercícios posteriores ao PCA em elaboração.</p>{demands.length ? <div className="checklist-box">{demands.map(row => <div className="checklist-row" key={row.demand.publicId}><span className="check-circle"><CalendarDays size={14} /></span><div><strong>{row.demand.title}</strong><small>{row.demand.publicId} · {row.unitName} · {formatMoney(row.demand.initialEstimatedValue)}</small><small>{row.demand.supplyLineCnaeCode ? `${row.demand.supplyLineCnaeCode} · ${row.demand.supplyLineCnaeDescription || "Linha CNAE"}` : "Linha de fornecimento ainda não registrada"}</small></div><Status tone="warning">{friendlyStatus(row.demand.status).text}</Status></div>)}</div> : <p className="task-empty">Não há DFDs com impacto financeiro em exercícios futuros.</p>}</section>;
}

function Agenda({ go, selectProcess }: { go: (screen: Exclude<Screen, "landing">) => void; selectProcess: (id: string) => void }) {
  const utils = trpc.useUtils();
  const board = trpc.planning.board.useQuery();
  const [selectedDemandIds, setSelectedDemandIds] = useState<string[]>([]);
  const [selectedDemandConsolidationIds, setSelectedDemandConsolidationIds] = useState<string[]>([]);
  const [selectedDirectPcaDemandIds, setSelectedDirectPcaDemandIds] = useState<string[]>([]);
  const [showOnlySupervening, setShowOnlySupervening] = useState(false);
  const [controlledDemandPublicId, setControlledDemandPublicId] = useState<string | null>(null);
  const createDemandConsolidation = trpc.planning.createDemandConsolidation.useMutation({ onSuccess: () => { setSelectedDemandIds([]); utils.planning.board.invalidate(); } });
  const createPca = trpc.planning.createPca.useMutation({ onSuccess: () => { setSelectedDemandConsolidationIds([]); setSelectedDirectPcaDemandIds([]); utils.planning.board.invalidate(); } });
  const submitPca = trpc.planning.submitPca.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const decidePca = trpc.planning.decidePca.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const publishPca = trpc.planning.publishPca.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const createOpeningRequest = trpc.planning.createOpeningRequest.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const decideOpeningRequest = trpc.planning.decideOpeningRequest.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const instantiateProcess = trpc.planning.instantiateProcess.useMutation({ onSuccess: async result => { await Promise.all([utils.planning.board.invalidate(), utils.procurement.list.invalidate(), utils.dashboard.summary.invalidate()]); selectProcess(result.publicId); go("trilha"); } });
  const toggle = (setter: React.Dispatch<React.SetStateAction<string[]>>, publicId: string) => setter(current => current.includes(publicId) ? current.filter(item => item !== publicId) : [...current, publicId]);
  const submitDemandConsolidation = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createDemandConsolidation.mutate({ title: String(data.get("title") ?? ""), notes: String(data.get("notes") ?? "") || undefined, demandPublicIds: selectedDemandIds }); };
  const submitNewPca = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createPca.mutate({ title: String(data.get("title") ?? ""), planId: Number(data.get("planId")), demandConsolidationPublicIds: selectedDemandConsolidationIds, demandPublicIds: selectedDirectPcaDemandIds }); };
  const decide = (pcaPublicId: string, action: "approve" | "return" | "reject") => { const notes = window.prompt(action === "approve" ? "Registre a motivação da autorização para publicação:" : "Registre a motivação da decisão:"); if (notes?.trim()) decidePca.mutate({ pcaPublicId, action, notes: notes.trim() }); };
  const publish = (pcaPublicId: string) => { const publicationReference = window.prompt("Informe o identificador, URL ou comprovante da publicação do PCA:"); if (publicationReference?.trim()) publishPca.mutate({ pcaPublicId, publicationReference: publicationReference.trim() }); };
  const submitOpening = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createOpeningRequest.mutate({ demandPublicId: String(data.get("demandPublicId") ?? ""), proposedWorkflowType: String(data.get("proposedWorkflowType")) as "direct_contracting" | "bidding", proposedModality: String(data.get("proposedModality") ?? ""), justification: String(data.get("justification") ?? "") }); };
  const decideOpening = (publicId: string, action: "authorize" | "return" | "reject") => { const notes = window.prompt(action === "authorize" ? "Registre a autorização da abertura e da modalidade proposta:" : "Registre a motivação da decisão:"); if (notes?.trim()) decideOpeningRequest.mutate({ requestPublicId: publicId, action, notes: notes.trim() }); };
  const allDemandRows = uniqueAgendaRows((board.data?.demands ?? []).map(row => ({ ...row, id: row.demand.id })));
  const eligibleDemands = allDemandRows.filter(row => ["submitted", "under_review", "accepted", "returned"].includes(row.demand.status));
  const futureFiscalImpactDemands = allDemandRows.filter(row => row.demand.hasFutureFiscalImpact);
  const visibleEligibleDemands = filterSuperveningDemands(eligibleDemands, showOnlySupervening);
  const superveningDeadlineByDemand = new globalThis.Map(superveningApprovalDeadlineAlerts(eligibleDemands, board.data?.alerts ?? []).map(alert => [alert.demandPublicId, alert.dueAt]));
  const demandConsolidations = uniqueAgendaRows(board.data?.demandConsolidations ?? []);
  const readyDemandConsolidations = demandConsolidations.filter(group => group.status === "ready_for_pca");
  const pcas = uniqueAgendaRows(board.data?.pcas ?? []);
  const publishedDemands = uniqueAgendaRows((board.data?.demands ?? []).map(row => ({ ...row, id: row.demand.id }))).filter(row => row.demand.status === "published_in_pca");
  const plans = uniqueAgendaRows(board.data?.plans ?? []);
  const modalityItems = (board.data?.referenceLists ?? []).find(list => list.code === "MODALIDADES_CONTRATACAO")?.items ?? [];
  const pcaStatusLabel = (status: string) => status === "draft" ? "Aguardando documento" : status === "ready_for_review" ? "Pronto para encaminhar" : status === "presidency_review" ? "Aguardando Presidência" : status === "approved_for_publication" ? "Autorizado para publicação" : status === "published" ? "Publicado" : status === "returned" ? "Devolvido para ajuste" : status === "rejected" ? "Não aprovado" : presentationStatus(status).text;
  return <AppShell active="agenda" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Planejamento / Agenda" title="AGENDA — Demandas e PCA" subtitle="Primeiro consolide DFDs semelhantes. Depois reúna as consolidações em um documento PCA único para deliberação e publicação." actions={<button className="button button-ink button-sm" onClick={() => go("porta")}><Plus size={15} /> Nova DFD</button>} />
    {board.isLoading ? <LoadingPanel message="Carregando demandas e planejamentos…" /> : board.error ? <EmptyState icon={<AlertTriangle size={28} />} title="Planejamento indisponível" text={board.error.message} /> : <>
      <section className="metric-grid"><Metric label="DFD em triagem" value={String(eligibleDemands.length)} detail="Disponíveis para consolidação" icon={<FileText size={16} />} /><Metric label="Consolidações prontas" value={String(readyDemandConsolidations.length)} detail="Disponíveis para compor um PCA" icon={<Layers size={16} />} /><Metric label="PCA na Presidência" value={String(pcas.filter(pca => pca.status === "presidency_review").length)} detail="Aguardando deliberação" icon={<Landmark size={16} />} /><Metric label="PCA publicados" value={String(pcas.filter(pca => pca.status === "published").length)} detail="Disponíveis ao Setor de Compras" tone="success" icon={<Check size={16} />} /></section>
      <section className="surface-panel dfd-control-entry"><div className="panel-heading"><div><span className="panel-kicker">GESTÃO INDIVIDUAL</span><h2>Abrir e acompanhar uma DFD</h2></div><Eye size={20} /></div><p className="trilha-current-copy">Consulte os dados completos, registre análise, solicite complementações e acompanhe o vínculo da DFD com a futura contratação.</p>{visibleEligibleDemands.length ? <div className="checklist-box">{visibleEligibleDemands.map(row => <div className="checklist-row" key={`control-${row.id}`}><span className="check-circle"><FileText size={14} /></span><div><strong>{row.demand.title}</strong><small>{row.demand.publicId} · {row.unitName} · {friendlyStatus(row.demand.status).text}</small></div><button className="button button-outline button-sm" type="button" onClick={() => setControlledDemandPublicId(row.demand.publicId)}>Abrir DFD <ArrowRight size={14} /></button></div>)}</div> : <p className="task-empty">Não há DFD em triagem para controle individual neste momento.</p>}</section>
      <section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">PAC / PLANEJAMENTO ANUAL</span><h2>Itens disponíveis para referência</h2></div><CalendarDays size={20} /></div>{board.data?.planItems.length ? <div className="data-table"><table><thead><tr><th>Código</th><th>Objeto</th><th>Exercício</th><th>Unidade</th><th>Estimativa</th><th>Situação</th></tr></thead><tbody>{uniqueAgendaRows(board.data.planItems.map(row => ({ ...row, id: row.item.id }))).map(row => <tr key={row.id}><td><strong>{row.item.code}</strong></td><td>{row.item.title}</td><td>{row.fiscalYear}</td><td>{row.unitName || "Não definida"}</td><td>{formatMoney(row.item.estimatedValue)}</td><td><Status tone={row.item.status === "completed" ? "success" : row.item.status === "in_progress" ? "info" : "neutral"}>{friendlyStatus(row.item.status).text}</Status></td></tr>)}</tbody></table></div> : <p className="task-empty">Nenhum item de PAC cadastrado. O perfil administrador pode incluí-los em ADMINISTRAÇÃO.</p>}</section>
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ETAPA 1 / DIRETORIA DE ADMINISTRAÇÃO</span><h2>DFD recebidas</h2></div><div className="inline-actions"><button className={`text-button ${showOnlySupervening ? "is-active" : ""}`} type="button" onClick={() => setShowOnlySupervening(current => !current)}>{showOnlySupervening ? "Ver todas" : `Supervenientes (${eligibleDemands.filter(row => row.demand.isSupervening).length})`}</button><FileText size={20} /></div></div>{visibleEligibleDemands.length ? <div className="checklist-box">{visibleEligibleDemands.map(row => <label className="checklist-row" key={row.id}><input type="checkbox" checked={selectedDemandIds.includes(row.demand.publicId)} onChange={() => toggle(setSelectedDemandIds, row.demand.publicId)} /><div><strong>{row.demand.title}{row.demand.isSupervening ? <span className="supervening-badge"><AlertTriangle size={12} aria-hidden="true" /> Superveniente</span> : null}</strong><small>{row.demand.publicId} · {row.unitName} · {formatMoney(row.demand.initialEstimatedValue)}</small>{superveningDeadlineByDemand.get(row.demand.publicId) ? <small className="supervening-deadline"><Clock3 size={12} aria-hidden="true" /> Prazo de análise: {formatDate(superveningDeadlineByDemand.get(row.demand.publicId))}</small> : null}</div><Status tone={row.demand.isSupervening ? "warning" : "info"}>{friendlyStatus(row.demand.status).text}</Status></label>)}</div> : <p className="task-empty">{showOnlySupervening ? "Não há DFD superveniente aguardando análise neste momento." : "Não há DFD disponíveis para consolidação neste momento."}</p>}</article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ETAPA 1 / CONSOLIDAÇÃO</span><h2>Formar consolidação de demandas</h2></div><Layers size={20} /></div><form className="form-stack" onSubmit={submitDemandConsolidation}><Field label="Título da consolidação" full><input name="title" required minLength={5} placeholder="Ex.: Mobiliário e equipamentos de escritório" /></Field><Field label="Observações de agrupamento" full><textarea name="notes" placeholder="Registre o critério de similaridade e qualquer orientação administrativa." /></Field><p className="task-empty">{selectedDemandIds.length} DFD(s) selecionada(s). Esta ação ainda não cria nem encaminha um PCA.</p>{createDemandConsolidation.error ? <p className="form-error">{createDemandConsolidation.error.message}</p> : null}<button className="button button-ink button-sm" type="submit" disabled={!selectedDemandIds.length || createDemandConsolidation.isPending}>{createDemandConsolidation.isPending ? "Consolidando…" : "Consolidar DFDs"} <ArrowRight size={15} /></button></form></article></section>
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ETAPA 1 CONCLUÍDA</span><h2>Consolidações de demandas</h2></div><Layers size={20} /></div>{demandConsolidations.length ? <div className="checklist-box">{demandConsolidations.map(group => <label className="checklist-row" key={group.id}><input type="checkbox" disabled={group.status !== "ready_for_pca"} checked={selectedDemandConsolidationIds.includes(group.publicId)} onChange={() => toggle(setSelectedDemandConsolidationIds, group.publicId)} /><div><strong>{group.title}</strong><small>{group.publicId} · {group.demandDetails.length} DFD(s) · {group.demandDetails.map(demand => demand.publicId).join(", ")}</small></div><Status tone={group.status === "ready_for_pca" ? "success" : group.status === "returned" ? "warning" : "neutral"}>{group.status === "ready_for_pca" ? "Pronta para o PCA" : group.status === "included_in_pca" ? "Já integrada a um PCA" : group.status === "returned" ? "Devolvida para ajuste" : group.status}</Status></label>)}</div> : <p className="task-empty">As consolidações aparecerão aqui após o agrupamento das DFDs.</p>}</article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ETAPA 2 / PCA ÚNICO</span><h2>Elaborar PCA a partir das consolidações</h2></div><CalendarDays size={20} /></div><form className="form-stack" onSubmit={submitNewPca}><Field label="Título do PCA" full><input name="title" required minLength={5} placeholder="Ex.: PCA de infraestrutura e serviços — 2027" /></Field><Field label="Planejamento anual" full><select name="planId" required defaultValue=""><option value="" disabled>Selecione o exercício anual</option>{plans.map(plan => <option key={plan.id} value={plan.id}>{plan.fiscalYear} · {plan.title}</option>)}</select></Field><p className="task-empty">{selectedDemandConsolidationIds.length} consolidação(ões) selecionada(s). O PCA será criado em rascunho, sem documento e sem encaminhamento automático.</p>{createPca.error ? <p className="form-error">{createPca.error.message}</p> : null}<button className="button button-ink button-sm" type="submit" disabled={!selectedDemandConsolidationIds.length || createPca.isPending}>{createPca.isPending ? "Criando PCA…" : "Criar rascunho do PCA"} <ArrowRight size={15} /></button></form></article></section>
      <section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ETAPA 2 / PRESIDÊNCIA E PUBLICAÇÃO</span><h2>PCA únicos</h2></div><Landmark size={20} /></div>{pcas.length ? <div className="data-table"><table><thead><tr><th>PCA</th><th>Consolidações e DFDs</th><th>Situação</th><th>Documento, deliberação e publicação</th></tr></thead><tbody>{pcas.map(pca => <tr key={pca.id}><td><strong>{pca.title}</strong><small>{pca.publicId}</small></td><td><strong>{pca.demandConsolidations.length} consolidação(ões)</strong><details className="pca-demand-details"><summary>Ver composição</summary><table><thead><tr><th>Origem</th><th>DFD</th><th>Unidade</th><th>Objeto</th><th>Estimativa</th></tr></thead><tbody>{pca.demandDetails.map(demand => <tr key={demand.publicId}><td>{demand.origin}</td><td>{demand.publicId}</td><td>{demand.unitName}</td><td>{demand.title}</td><td>{formatMoney(demand.estimatedValue)}</td></tr>)}</tbody></table></details></td><td><Status tone={pca.status === "published" || pca.status === "approved_for_publication" ? "success" : pca.status === "returned" || pca.status === "rejected" ? "warning" : "info"}>{pcaStatusLabel(pca.status)}</Status></td><td><div className="tag-row"><PcaDocumentActions pca={pca} />{["ready_for_review", "returned"].includes(pca.status) ? <button className="text-button" onClick={() => submitPca.mutate({ pcaPublicId: pca.publicId })}>Enviar à Presidência</button> : null}{pca.status === "presidency_review" ? <><button className="text-button" onClick={() => decide(pca.publicId, "approve")}>Autorizar</button><button className="text-button" onClick={() => decide(pca.publicId, "return")}>Devolver</button><button className="text-button" onClick={() => decide(pca.publicId, "reject")}>Rejeitar</button></> : null}{pca.status === "approved_for_publication" ? <button className="text-button" onClick={() => publish(pca.publicId)}>Registrar publicação</button> : null}{pca.status === "published" ? <><span>Publicado: {pca.publicationReference || "sem referência"}</span>{pca.updates.length ? <div className="checklist-box">{pca.updates.map(update => <PcaUpdateActions key={update.id} update={update} />)}</div> : <small>Sem atualização publicada ou em elaboração.</small>}</> : null}</div></td></tr>)}</tbody></table></div> : <EmptyState icon={<CalendarDays size={26} />} title="Nenhum PCA elaborado" text="Primeiro consolide DFDs semelhantes; depois selecione as consolidações ou DFDs isoladas para criar o rascunho do PCA anual." />}</section>
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">SETOR DE COMPRAS</span><h2>Solicitar abertura de contratação</h2></div><Target size={20} /></div>{publishedDemands.length ? <form className="form-stack" onSubmit={submitOpening}><Field label="DFD publicada no PCA" full><select name="demandPublicId" required>{publishedDemands.map(row => <option key={row.id} value={row.demand.publicId}>{row.demand.publicId} · {row.demand.title}</option>)}</select></Field><Field label="Trilha proposta"><select name="proposedWorkflowType" defaultValue="direct_contracting"><option value="direct_contracting">Contratação direta</option><option value="bidding">Licitação</option></select></Field><Field label="Modalidade proposta">{modalityItems.length ? <select name="proposedModality" required defaultValue=""><option value="" disabled>Selecione uma modalidade configurada</option>{uniqueAgendaRows(modalityItems).map(item => <option key={item.id} value={item.label}>{item.label}</option>)}</select> : <input name="proposedModality" required placeholder="Ex.: Dispensa de licitação" />}</Field><Field label="Justificativa para abertura" full><textarea name="justification" required minLength={10} placeholder="Fundamente a abertura e a modalidade proposta para decisão da Presidência." /></Field>{createOpeningRequest.error ? <p className="form-error">{createOpeningRequest.error.message}</p> : null}<button className="button button-ink button-sm" type="submit" disabled={createOpeningRequest.isPending}>Enviar à Presidência <ArrowRight size={15} /></button></form> : <p className="task-empty">O Setor de Compras receberá DFD somente após a publicação do PCA.</p>}</article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">PRESIDÊNCIA E COMPRAS</span><h2>Aberturas autorizadas</h2></div><ShieldCheck size={20} /></div>{board.data?.openingRequests.length ? <div className="checklist-box">{uniqueAgendaRows(board.data.openingRequests.map(item => ({ ...item, id: item.request.id }))).map(item => <div className="checklist-row" key={item.id}><span className="check-circle"><Target size={14} /></span><div><strong>{item.demandPublicId} · {item.demandTitle}</strong><small>{item.request.publicId} · {item.pcaPublicId || "PCA não identificado"} · {item.request.proposedModality}</small></div><div className="tag-row">{item.request.status === "presidency_review" ? <><button className="text-button" onClick={() => decideOpening(item.request.publicId, "authorize")}>Autorizar</button><button className="text-button" onClick={() => decideOpening(item.request.publicId, "return")}>Devolver</button><button className="text-button" onClick={() => decideOpening(item.request.publicId, "reject")}>Rejeitar</button></> : item.request.status === "authorized" ? <button className="text-button" onClick={() => instantiateProcess.mutate({ requestPublicId: item.request.publicId })}>Instaurar processo</button> : <Status tone={item.request.status === "instantiated" ? "success" : item.request.status === "rejected" ? "danger" : "info"}>{friendlyStatus(item.request.status).text}</Status>}</div></div>)}</div> : <p className="task-empty">Nenhuma solicitação de abertura foi registrada.</p>}</article></section>
      <AnnualPcaDirectDemandPanel />
      <FutureFiscalImpactReport demands={futureFiscalImpactDemands} />
      <PlanningChecklistPanel items={board.data?.checklists ?? []} />
      <PlanningDeadlineAlerts alerts={board.data?.alerts ?? []} />
      {controlledDemandPublicId ? <><DemandControlDialog demandPublicId={controlledDemandPublicId} open={Boolean(controlledDemandPublicId)} onOpenChange={isOpen => { if (!isOpen) setControlledDemandPublicId(null); }} modalityItems={modalityItems} openProcess={publicId => { setControlledDemandPublicId(null); selectProcess(publicId); go("trilha"); }} /><DemandPdfExportAction demandPublicId={controlledDemandPublicId} /></> : null}
    </>}</AppShell>;
}

const PROCESS_ROLE_OPTIONS = ["demandante", "chefia_compras", "compras", "instrumentalizacao", "contabilidade", "juridico", "encarregado_lgpd", "agente_contratacao", "autoridade_competente", "gestao_contratos", "fiscal_contrato", "administrador"];

function ProfilesPage({ go, units }: { go: (screen: Exclude<Screen, "landing">) => void; units: { id: number; name: string; code: string }[] }) {
  const utils = trpc.useUtils();
  const directory = trpc.workspace.directory.useQuery();
  const assign = trpc.workspace.assignRole.useMutation({ onSuccess: () => utils.workspace.directory.invalidate() });
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    assign.mutate({ userId: Number(data.get("userId")), unitId: Number(data.get("unitId")), role: String(data.get("role")) as "demandante" | "chefia_compras" | "compras" | "instrumentalizacao" | "contabilidade" | "juridico" | "encarregado_lgpd" | "agente_contratacao" | "autoridade_competente" | "gestao_contratos" | "fiscal_contrato" | "administrador" });
  };
  return <AppShell active="perfis" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Perfis" title="PERFIS — Atribuições institucionais" subtitle="Defina quem pode atuar em cada responsabilidade do fluxo, preservando segregação de funções." />
    <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">Nova atribuição</span><h2>Vincular responsabilidade</h2></div><ShieldCheck size={20} /></div><form className="form-stack" onSubmit={submit}><Field label="Conta institucional"><select name="userId" required>{directory.data?.map(item => <option key={item.id} value={item.id}>{item.name || "Sem nome"}{item.email ? ` · ${item.email}` : ""}</option>)}</select></Field><Field label="Unidade"><select name="unitId" required>{units.map(unit => <option key={unit.id} value={unit.id}>{unit.name} · {unit.code}</option>)}</select></Field><Field label="Perfil de processo" full><select name="role" required>{PROCESS_ROLE_OPTIONS.map(role => <option key={role} value={role}>{friendlyRole(role)}</option>)}</select></Field>{assign.error ? <p className="form-error">{assign.error.message}</p> : null}<button className="button button-ink button-sm" type="submit" disabled={assign.isPending}>{assign.isPending ? "Atribuindo…" : "Atribuir perfil"} <ArrowRight size={15} /></button></form><p className="task-empty">As contas aparecem aqui após o primeiro acesso autenticado. Não são criados usuários fictícios.</p></article>
      <article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">Diretório</span><h2>Contas e atribuições</h2></div><Users size={20} /></div>{directory.isLoading ? <LoadingPanel message="Carregando diretório…" /> : directory.error ? <p className="form-error">{directory.error.message}</p> : directory.data?.length ? <div className="checklist-box">{directory.data.map(item => <div className="profile-row" key={item.id}><span className="profile-avatar">{(item.name || "U").slice(0, 1).toUpperCase()}</span><div><strong>{item.name || "Usuário institucional"}</strong><small>{item.email || "E-mail não disponível"} · {item.platformRole === "admin" ? "Administrador da plataforma" : "Usuário"}</small><div className="tag-row">{item.assignments.length ? item.assignments.map(assignment => <span key={assignment.id}>{friendlyRole(assignment.role)} · {assignment.unitName || "Global"}</span>) : <span>Sem perfil de processo</span>}</div></div></div>)}</div> : <EmptyState icon={<Users size={26} />} title="Nenhuma conta cadastrada" text="As contas serão registradas no primeiro acesso institucional." />}</article></section>
  </AppShell>;
}

function LocalAccountsPage({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const utils = trpc.useUtils();
  const accounts = trpc.administration.localAccounts.useQuery();
  const create = trpc.administration.createLocalAccount.useMutation({ onSuccess: () => utils.administration.localAccounts.invalidate() });
  const update = trpc.administration.updateLocalAccount.useMutation({ onSuccess: () => utils.administration.localAccounts.invalidate() });
  const resetPassword = trpc.administration.resetLocalAccountPassword.useMutation({ onSuccess: () => utils.administration.localAccounts.invalidate() });
  const [selectedUserId, setSelectedUserId] = useState<number | null>(null);
  const [accountSearch, setAccountSearch] = useState("");
  const [accountStatus, setAccountStatus] = useState<LocalAccountFilterStatus>("all");
  const accountData = accounts.data ?? { accounts: [], recoveryRequests: [] };
  const filteredAccounts = useMemo(() => filterLocalAccounts(accountData.accounts, accountSearch, accountStatus), [accountData.accounts, accountSearch, accountStatus]);
  const selected = accountData.accounts.find(account => account.id === selectedUserId) ?? null;
  const createAccount = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); create.mutate({ name: String(form.get("name") ?? ""), email: String(form.get("email") ?? ""), password: String(form.get("password") ?? ""), role: String(form.get("role")) as "user" | "admin" }, { onSuccess: () => event.currentTarget.reset() }); };
  const saveAccount = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; const form = new FormData(event.currentTarget); update.mutate({ userId: selected.id, name: String(form.get("name") ?? ""), email: String(form.get("email") ?? ""), role: String(form.get("role")) as "user" | "admin", active: form.get("active") === "on" }); };
  const changePassword = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; const password = String(new FormData(event.currentTarget).get("password") ?? ""); resetPassword.mutate({ userId: selected.id, password }, { onSuccess: () => event.currentTarget.reset() }); };
  return <AppShell active="contas" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Administração" title="CONTAS LOCAIS" subtitle="Crie, edite, inative e recupere acessos da instalação independente." actions={<button className="button button-ghost button-sm" onClick={() => go("administracao")}><SlidersHorizontal size={15} /> Administração geral</button>} />
    {accounts.isLoading ? <LoadingPanel message="Carregando contas locais…" /> : accounts.error ? <EmptyState icon={<AlertTriangle size={28} />} title="Contas indisponíveis" text={accounts.error.message} /> : <>
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">NOVA CONTA</span><h2>Criar acesso local</h2></div><Plus size={20} /></div><form className="form-stack" onSubmit={createAccount}><Field label="Nome"><input name="name" required minLength={3} placeholder="Nome completo" /></Field><Field label="E-mail"><input name="email" required type="email" placeholder="servidor@fozdoiguacu.pr.leg.br" /></Field><Field label="Perfil"><select name="role" defaultValue="user"><option value="user">Usuário</option><option value="admin">Administrador</option></select></Field><Field label="Senha inicial" full><input name="password" required type="password" minLength={12} autoComplete="new-password" placeholder="Mínimo de 12 caracteres, com letras e números" /><small>A senha não fica visível novamente após a criação.</small></Field>{create.error ? <p className="form-error">{create.error.message}</p> : null}<button className="button button-ink" disabled={create.isPending} type="submit">{create.isPending ? "Criando…" : "Criar conta local"}</button></form></article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">RECUPERAÇÃO ASSISTIDA</span><h2>Solicitações pendentes</h2></div><CircleHelp size={20} /></div><p className="trilha-current-copy">Nesta implantação inicial, a recuperação não envia e-mail: o administrador redefine a senha de forma auditável.</p>{accountData.recoveryRequests.length ? <div className="checklist-box">{accountData.recoveryRequests.map(request => <div className="checklist-row" key={request.id}><span className="check-circle"><CircleHelp size={14} /></span><div><strong>{request.name || "Usuário institucional"}</strong><small>{request.email} · solicitada em {formatDate(request.requestedAt)}</small></div><button className="text-button" onClick={() => setSelectedUserId(request.userId)}>Redefinir senha</button></div>)}</div> : <p className="task-empty">Nenhuma solicitação de recuperação pendente.</p>}</article></section>
      <section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ACESSOS CADASTRADOS</span><h2>{filteredAccounts.length} de {accountData.accounts.length} conta(s) local(is)</h2></div><Status tone="info">Gestão administrativa</Status></div><div className="table-tools local-account-tools"><label className="table-search"><Search size={16} /><input value={accountSearch} onChange={event => setAccountSearch(event.target.value)} placeholder="Buscar por nome ou e-mail" aria-label="Buscar por nome ou e-mail" /></label><label className="field"><span>Situação</span><select value={accountStatus} onChange={event => setAccountStatus(event.target.value as LocalAccountFilterStatus)}><option value="all">Todas as contas</option><option value="active">Somente ativas</option><option value="inactive">Somente inativas</option></select></label></div>{filteredAccounts.length ? <div className="catalog-items">{filteredAccounts.map(account => <article className="catalog-item" key={account.id}><span className="catalog-order">{String(account.id).padStart(2, "0")}</span><div><strong>{account.name || "Sem nome"}</strong><small>{account.email} · último acesso {account.lastSignedIn.getTime() > 0 ? formatDate(account.lastSignedIn) : "ainda não acessou"}</small></div><div className="tag-row"><Status tone={account.active ? "success" : "neutral"}>{account.active ? "Ativa" : "Inativa"}</Status><Status tone={account.role === "admin" ? "info" : "neutral"}>{account.role === "admin" ? "Administradora" : "Usuária"}</Status><button className="text-button" onClick={() => setSelectedUserId(account.id)}>Gerenciar</button></div></article>)}</div> : <EmptyState icon={<Search size={26} />} title="Nenhuma conta encontrada" text="Altere a busca ou o filtro de situação para localizar outra conta." />}</section>
      {selected ? <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">EDITAR CONTA</span><h2>{selected.name || selected.email}</h2></div><button className="text-button" onClick={() => setSelectedUserId(null)}>Fechar</button></div><form key={selected.id} className="form-stack" onSubmit={saveAccount}><Field label="Nome"><input name="name" required minLength={3} defaultValue={selected.name || ""} /></Field><Field label="E-mail"><input name="email" required type="email" defaultValue={selected.email || ""} /></Field><Field label="Perfil"><select name="role" defaultValue={selected.role}><option value="user">Usuário</option><option value="admin">Administrador</option></select></Field><Field label="Situação" full><label className="checkbox-line"><input name="active" type="checkbox" defaultChecked={selected.active} /> Conta ativa para acesso local</label></Field>{update.error ? <p className="form-error">{update.error.message}</p> : null}<button className="button button-ink" type="submit" disabled={update.isPending}>{update.isPending ? "Salvando…" : "Salvar alterações"}</button></form></article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">NOVA SENHA</span><h2>Redefinir acesso</h2></div><ShieldCheck size={20} /></div><p className="trilha-current-copy">A redefinição encerra as solicitações pendentes de recuperação para esta conta e fica registrada na auditoria.</p><form className="form-stack" onSubmit={changePassword}><Field label="Nova senha" full><input name="password" type="password" required minLength={12} autoComplete="new-password" placeholder="Mínimo de 12 caracteres, com letras e números" /></Field>{resetPassword.error ? <p className="form-error">{resetPassword.error.message}</p> : null}<button className="button button-cyan" type="submit" disabled={resetPassword.isPending}>{resetPassword.isPending ? "Redefinindo…" : "Definir nova senha"}</button></form></article></section> : null}
    </>}</AppShell>;
}

function SettingsPage({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const utils = trpc.useUtils();
  const status = trpc.googleDrive.status.useQuery();
  const backups = trpc.administration.backupStatus.useQuery(undefined, { retry: false });
  const begin = trpc.googleDrive.beginAuthorization.useMutation({ onSuccess: data => window.location.assign(data.authorizationUrl) });
  const disconnect = trpc.googleDrive.disconnect.useMutation({ onSuccess: () => { utils.googleDrive.status.invalidate(); utils.googleDrive.connection.invalidate(); } });
  const setFolder = trpc.googleDrive.setRootFolder.useMutation({ onSuccess: () => utils.googleDrive.status.invalidate() });
  const connection = status.data?.connection;
  const submitFolder = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setFolder.mutate({ folder: String(new FormData(event.currentTarget).get("folder") ?? "") }); };
  const tone = status.data?.status === "ready" ? "success" : status.data?.status === "not_configured" || status.data?.status === "reconnect_required" ? "warning" : "info";
  const backupTone = !backups.data?.enabled ? "neutral" : backups.data.health?.status === "healthy" ? "success" : backups.data.health?.status === "not_started" ? "warning" : "danger";
  return <AppShell active="configuracoes" go={go} userName="" alertCount={backups.data?.enabled && backups.data.health?.status !== "healthy" ? 1 : 0} logout={() => undefined}><PageHeading eyebrow="Governança / Configurações" title="CONFIGURAÇÕES" subtitle="Acompanhe o Google Drive e a saúde dos backups desta instalação." actions={<button className="button button-ghost button-sm" onClick={() => go("oficina")}><LayoutTemplate size={15} /> Abrir OFICINA</button>} />
    {status.isLoading ? <LoadingPanel message="Verificando a integração Google Drive…" /> : status.error ? <EmptyState icon={<AlertTriangle size={28} />} title="Integração indisponível" text={status.error.message} /> : <><section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">GOOGLE DRIVE</span><h2>Status atual</h2></div><Status tone={tone}>{status.data?.status === "ready" ? "Pronta" : "Requer atenção"}</Status></div><p className="trilha-current-copy">{status.data?.message}</p><div className="checklist-box"><div className="checklist-row"><span className="check-circle">{status.data?.configured ? <Check size={14} /> : <AlertTriangle size={14} />}</span><div><strong>Credenciais OAuth institucionais</strong><small>{status.data?.configured ? "Configuradas no servidor local." : "Ainda não configuradas na instalação."}</small></div></div><div className="checklist-row"><span className="check-circle">{connection && !connection.revokedAt ? <Check size={14} /> : <CircleHelp size={14} />}</span><div><strong>Conta individual</strong><small>{connection?.googleEmail || "Nenhuma conta Google conectada."}</small></div></div><div className="checklist-row"><span className="check-circle">{connection?.rootFolderId ? <Check size={14} /> : <CircleHelp size={14} />}</span><div><strong>Pasta de destino</strong><small>{connection?.rootFolderId ? (connection.usingInstitutionalDefault ? "Pasta institucional padrão em uso." : "Pasta individual configurada.") : "Pasta ainda não definida."}</small></div></div></div><div className="inline-actions">{status.data?.configured && (!connection || connection.revokedAt) ? <button className="button button-ink button-sm" disabled={begin.isPending} onClick={() => begin.mutate()}>{begin.isPending ? "Abrindo…" : "Conectar Google Drive"}</button> : null}{connection && !connection.revokedAt ? <button className="button button-ghost button-sm" disabled={disconnect.isPending} onClick={() => { if (window.confirm("Desconectar sua conta Google desta instalação?")) disconnect.mutate(); }}>Desconectar conta</button> : null}</div>{begin.error || disconnect.error ? <p className="form-error">{begin.error?.message ?? disconnect.error?.message}</p> : null}</article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">DESTINO DOCUMENTAL</span><h2>Pasta do Drive</h2></div><FolderOpen size={20} /></div>{connection?.rootFolderUrl ? <a className="button button-ghost button-sm" href={connection.rootFolderUrl} target="_blank" rel="noreferrer"><FolderOpen size={15} /> Abrir pasta configurada</a> : null}<form className="form-stack" onSubmit={submitFolder}><Field label="Link ou identificador da pasta" full><input name="folder" required minLength={10} defaultValue={connection?.rootFolderId || ""} placeholder="Cole o link da pasta institucional no Google Drive" /><small>A opção fica disponível após a conexão da sua conta Google.</small></Field>{setFolder.error ? <p className="form-error">{setFolder.error.message}</p> : null}<button className="button button-cyan" type="submit" disabled={!connection || Boolean(connection.revokedAt) || setFolder.isPending}>{setFolder.isPending ? "Salvando…" : "Definir pasta de destino"}</button></form><p className="task-empty">Última utilização: {formatDate(connection?.lastUsedAt)}. Conexão realizada em {formatDate(connection?.connectedAt)}.</p></article></section><section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">BACKUP LOCAL</span><h2>Histórico e saúde</h2></div><Status tone={backupTone}>{!backups.data?.enabled ? "Disponível no modo local" : backups.data.health?.status === "healthy" ? "Em dia" : backups.data.health?.status === "failed" ? "Falhou" : backups.data.health?.status === "overdue" ? "Atrasado" : "Primeira cópia pendente"}</Status></div>{backups.isLoading ? <LoadingPanel message="Carregando histórico de backups…" /> : backups.error ? <p className="task-empty">O histórico completo é exibido somente a administradores institucionais. {backups.error.message}</p> : !backups.data?.enabled ? <p className="trilha-current-copy">O histórico de cópias é ativado automaticamente na edição auto-hospedada com autenticação local.</p> : <><p className="trilha-current-copy">{backups.data.health?.message} {backups.data.health?.lastCompletedAt ? `Última conclusão: ${formatDate(backups.data.health.lastCompletedAt)}.` : ""}</p>{backups.data.history.length ? <div className="catalog-items">{backups.data.history.map(item => <article className="catalog-item" key={item.id}><span className="catalog-order"><Archive size={16} /></span><div><strong>{item.status === "success" ? "Backup concluído" : "Backup com falha"}</strong><small>Concluído em {formatDate(item.completedAt)} · iniciado em {formatDate(item.startedAt)}{item.backupSizeBytes ? ` · ${Number(item.backupSizeBytes).toLocaleString("pt-BR")} bytes` : ""}</small>{item.errorSummary ? <small>{item.errorSummary}</small> : null}</div><Status tone={item.status === "success" ? "success" : "danger"}>{item.status === "success" ? "Concluído" : "Falhou"}</Status></article>)}</div> : <EmptyState icon={<Archive size={26} />} title="Nenhum backup registrado" text="Execute a cópia de teste do script Windows para iniciar o histórico." />}</>}</section></>}</AppShell>;
}

function AdministrationPage({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const utils = trpc.useUtils();
  const overview = trpc.administration.overview.useQuery();
  const planning = trpc.administration.planning.useQuery();
  const refresh = () => Promise.all([utils.administration.overview.invalidate(), utils.administration.planning.invalidate(), utils.procurement.planItems.invalidate()]);
  const createUnit = trpc.administration.createUnit.useMutation({ onSuccess: refresh });
  const setUnitStatus = trpc.administration.setUnitStatus.useMutation({ onSuccess: refresh });
  const saveSetting = trpc.administration.saveSetting.useMutation({ onSuccess: refresh });
  const createPlan = trpc.administration.createPlan.useMutation({ onSuccess: refresh });
  const createPlanItem = trpc.administration.createPlanItem.useMutation({ onSuccess: refresh });
  const saveTemplate = trpc.administration.saveTemplate.useMutation({ onSuccess: refresh });
  const createSupplier = trpc.administration.createSupplier.useMutation({ onSuccess: refresh });
  const saveReferenceList = trpc.administration.saveReferenceList.useMutation({ onSuccess: refresh });
  const saveReferenceListItem = trpc.administration.saveReferenceListItem.useMutation({ onSuccess: refresh });
  const submitUnit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createUnit.mutate({ name: String(data.get("name") ?? ""), code: String(data.get("code") ?? "") }); };
  const submitSetting = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); saveSetting.mutate({ category: String(data.get("category") ?? ""), settingKey: String(data.get("settingKey") ?? ""), label: String(data.get("label") ?? ""), value: String(data.get("value") ?? "") || undefined, description: String(data.get("description") ?? "") || undefined, active: data.get("active") === "on" }); };
  const submitPlan = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createPlan.mutate({ fiscalYear: Number(data.get("fiscalYear")), title: String(data.get("title") ?? ""), status: String(data.get("status")) as "draft" | "active" | "closed" }); };
  const submitPlanItem = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createPlanItem.mutate({ planId: Number(data.get("planId")), code: String(data.get("code") ?? ""), title: String(data.get("title") ?? ""), requestingUnitId: Number(data.get("requestingUnitId")) || undefined, estimatedValue: String(data.get("estimatedValue") ?? "") || undefined, status: String(data.get("status")) as "planned" | "in_progress" | "completed" | "changed" | "cancelled" }); };
  const submitTemplate = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); saveTemplate.mutate({ code: String(data.get("code") ?? ""), title: String(data.get("title") ?? ""), documentType: String(data.get("documentType") ?? ""), content: String(data.get("content") ?? "") || undefined, active: data.get("active") === "on" }); };
  const submitSupplier = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); createSupplier.mutate({ legalName: String(data.get("legalName") ?? ""), taxId: String(data.get("taxId") ?? ""), email: String(data.get("email") ?? "") || undefined, phone: String(data.get("phone") ?? "") || undefined, status: String(data.get("status")) as "active" | "pending_review" | "restricted" | "inactive", notes: String(data.get("notes") ?? "") || undefined }); };
  const submitReferenceList = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); saveReferenceList.mutate({ code: String(data.get("code") ?? ""), label: String(data.get("label") ?? ""), description: String(data.get("description") ?? "") || undefined, active: data.get("active") === "on" }); };
  const submitReferenceListItem = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); saveReferenceListItem.mutate({ listId: Number(data.get("listId")), value: String(data.get("value") ?? ""), label: String(data.get("label") ?? ""), sortOrder: Number(data.get("sortOrder")) || 0, active: data.get("active") === "on" }); };
  const anyError = createUnit.error ?? setUnitStatus.error ?? saveSetting.error ?? createPlan.error ?? createPlanItem.error ?? saveTemplate.error ?? createSupplier.error ?? saveReferenceList.error ?? saveReferenceListItem.error;
  if (overview.isLoading || planning.isLoading) return <LoadingPanel message="Carregando configuração administrativa…" />;
  if (overview.error || planning.error) return <AppShell active="administracao" go={go} userName="" alertCount={0} logout={() => undefined}><EmptyState icon={<AlertTriangle size={28} />} title="Administração indisponível" text={overview.error?.message ?? planning.error?.message ?? "Não foi possível carregar os parâmetros institucionais."} /></AppShell>;
  const data = overview.data;
  const planningData = planning.data;
  return <AppShell active="administracao" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Administração" title="ADMINISTRAÇÃO — Configuração institucional" subtitle="Mantenha unidades, parâmetros, planejamento, modelos e fornecedores com rastreabilidade." />
    <section className="metric-grid"><Metric label="Unidades ativas" value={String(data?.units.filter(unit => unit.active).length ?? 0)} detail="Estruturas disponíveis para demandas" icon={<Building2 size={16} />} /><Metric label="Parâmetros ativos" value={String(data?.settings.filter(setting => setting.active).length ?? 0)} detail="Regras institucionais configuradas" icon={<SlidersHorizontal size={16} />} /><Metric label="Modelos ativos" value={String(data?.templates.filter(template => template.active).length ?? 0)} detail="Documentos e checklists em uso" icon={<FileText size={16} />} /><Metric label="Fornecedores" value={String(data?.suppliers.length ?? 0)} detail="Diretório institucional cadastrado" icon={<Users size={16} />} /></section>
    {anyError ? <p className="form-error">{anyError.message}</p> : null}
    <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ESTRUTURA</span><h2>Unidades organizacionais</h2></div><Building2 size={20} /></div><form className="inline-task-form" onSubmit={submitUnit}><input name="name" required minLength={3} placeholder="Nome da unidade" /><input name="code" required minLength={2} placeholder="Sigla" /><button className="button button-ink button-sm" type="submit" disabled={createUnit.isPending}><Plus size={14} /> Adicionar</button></form><div className="checklist-box">{data?.units.map(unit => <div className="checklist-row" key={unit.id}><span className="check-circle"><Building2 size={15} /></span><div><strong>{unit.name}</strong><small>{unit.code}</small></div><button className="text-button" onClick={() => setUnitStatus.mutate({ unitId: unit.id, active: !unit.active })}>{unit.active ? "Inativar" : "Ativar"}</button></div>)}</div></article>
      <article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">GOVERNANÇA</span><h2>Parâmetros institucionais</h2></div><SlidersHorizontal size={20} /></div><form className="form-stack" onSubmit={submitSetting}><Field label="Categoria"><input name="category" required placeholder="Ex.: transparência" /></Field><Field label="Chave"><input name="settingKey" required placeholder="Ex.: prazo.publicacao" /></Field><Field label="Rótulo" full><input name="label" required placeholder="Ex.: Prazo interno de publicação" /></Field><Field label="Valor" full><input name="value" placeholder="Ex.: 2 dias úteis" /></Field><Field label="Orientação" full><textarea name="description" placeholder="Descreva como o parâmetro deve ser aplicado." /></Field><Field label="Situação" full><label className="checkbox-line"><input type="checkbox" name="active" defaultChecked /> Parâmetro ativo</label></Field><button className="button button-ink button-sm" type="submit" disabled={saveSetting.isPending}>Salvar parâmetro <Check size={15} /></button></form><div className="tag-row">{data?.settings.map(setting => <span key={setting.id}>{setting.label}: {setting.value || "sem valor"}</span>)}</div></article></section>
    <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">AGENDA</span><h2>Planejamento anual</h2></div><CalendarDays size={20} /></div><form className="inline-task-form" onSubmit={submitPlan}><input name="fiscalYear" required type="number" min="2020" max="2100" defaultValue={new Date().getFullYear()} /><input name="title" required placeholder="Título do planejamento" /><select name="status" defaultValue="draft"><option value="draft">Rascunho</option><option value="active">Ativo</option><option value="closed">Encerrado</option></select><button className="button button-ink button-sm" type="submit" disabled={createPlan.isPending}><Plus size={14} /> Criar</button></form><div className="checklist-box">{planningData?.plans.map(plan => <div className="checklist-row" key={plan.id}><span className="check-circle"><CalendarDays size={15} /></span><div><strong>{plan.title}</strong><small>Exercício {plan.fiscalYear}</small></div><Status tone={plan.status === "active" ? "success" : "neutral"}>{friendlyStatus(plan.status).text}</Status></div>)}</div></article>
      <article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">PAC</span><h2>Adicionar item ao planejamento</h2></div><Plus size={20} /></div>{planningData?.plans.length ? <form className="form-stack" onSubmit={submitPlanItem}><Field label="Planejamento"><select name="planId" required>{planningData.plans.map(plan => <option key={plan.id} value={plan.id}>{plan.fiscalYear} · {plan.title}</option>)}</select></Field><Field label="Código"><input name="code" required placeholder="Ex.: PAC-2026-001" /></Field><Field label="Objeto" full><input name="title" required placeholder="Descrição resumida da necessidade planejada" /></Field><Field label="Unidade"><select name="requestingUnitId"><option value="">Sem unidade definida</option>{data?.units.filter(unit => unit.active).map(unit => <option key={unit.id} value={unit.id}>{unit.name}</option>)}</select></Field><Field label="Estimativa"><input name="estimatedValue" type="number" min="0" step="0.01" placeholder="0,00" /></Field><Field label="Situação" full><select name="status" defaultValue="planned"><option value="planned">Planejado</option><option value="in_progress">Em execução</option><option value="completed">Concluído</option><option value="changed">Alterado</option><option value="cancelled">Cancelado</option></select></Field><button className="button button-ink button-sm" type="submit" disabled={createPlanItem.isPending}>Adicionar ao PAC <Plus size={15} /></button></form> : <p className="task-empty">Crie primeiro um planejamento anual para incluir itens do PAC.</p>}</article></section>
    <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">OFICINA</span><h2>Modelos institucionais</h2></div><FileText size={20} /></div><form className="form-stack" onSubmit={submitTemplate}><Field label="Código"><input name="code" required placeholder="Ex.: DFD-BASE" /></Field><Field label="Tipo de modelo"><select name="documentType" required defaultValue="DOCUMENTO_GERAL"><option value="DOCUMENTO_GERAL">Documento ou orientação geral</option><option value="CHECKLIST_DFD">Checklist de DFD</option><option value="CHECKLIST_PCA">Checklist de PCA</option><option value="CHECKLIST_ABERTURA">Checklist de solicitação de abertura</option></select></Field><Field label="Título" full><input name="title" required placeholder="Nome do modelo" /></Field><Field label="Conteúdo / orientação" full><textarea name="content" placeholder="Para checklist, informe um item por linha. Para documento, registre estrutura, instruções ou texto-base." /></Field><Field label="Situação" full><label className="checkbox-line"><input type="checkbox" name="active" defaultChecked /> Modelo ativo</label></Field><button className="button button-ink button-sm" type="submit" disabled={saveTemplate.isPending}>Salvar versão <FileCheck2 size={15} /></button></form><div className="tag-row">{data?.templates.map(template => <span key={template.id}>{template.code} · v{template.version}</span>)}</div></article>
      <article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">ÍMÃ</span><h2>Diretório de fornecedores</h2></div><Users size={20} /></div><form className="form-stack" onSubmit={submitSupplier}><Field label="Razão social" full><input name="legalName" required placeholder="Nome empresarial ou nome completo" /></Field><Field label="CPF/CNPJ"><input name="taxId" required placeholder="Somente números ou pontuação" /></Field><Field label="E-mail"><input name="email" type="email" placeholder="contato@fornecedor.com" /></Field><Field label="Telefone"><input name="phone" placeholder="(00) 00000-0000" /></Field><Field label="Situação"><select name="status" defaultValue="pending_review"><option value="pending_review">Em revisão</option><option value="active">Ativo</option><option value="restricted">Restrito</option><option value="inactive">Inativo</option></select></Field><Field label="Observações" full><textarea name="notes" placeholder="Registre apenas informações administrativas necessárias." /></Field><button className="button button-ink button-sm" type="submit" disabled={createSupplier.isPending}>Cadastrar fornecedor <Plus size={15} /></button></form><div className="tag-row">{data?.suppliers.map(supplier => <span key={supplier.id}>{supplier.legalName} · {supplier.status}</span>)}</div></article></section>
    <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">CATÁLOGOS</span><h2>Listas configuráveis</h2></div><ListChecks size={20} /></div><p className="trilha-current-copy">Crie listas reutilizáveis para opções institucionais. A lista <strong>MODALIDADES_CONTRATACAO</strong> passa a orientar a solicitação de abertura.</p><form className="form-stack" onSubmit={submitReferenceList}><Field label="Código"><input name="code" required placeholder="Ex.: MODALIDADES_CONTRATACAO" /></Field><Field label="Nome" full><input name="label" required placeholder="Ex.: Modalidades de contratação" /></Field><Field label="Descrição" full><textarea name="description" placeholder="Finalidade e regras de uso da lista." /></Field><Field label="Situação" full><label className="checkbox-line"><input type="checkbox" name="active" defaultChecked /> Lista ativa</label></Field><button className="button button-ink button-sm" type="submit" disabled={saveReferenceList.isPending}>Salvar lista <Plus size={15} /></button></form><div className="tag-row">{data?.referenceLists.map(list => <span key={list.id}>{list.code} · {list.items.length} item(ns)</span>)}</div></article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">CATÁLOGOS</span><h2>Itens da lista</h2></div><SlidersHorizontal size={20} /></div>{data?.referenceLists.length ? <form className="form-stack" onSubmit={submitReferenceListItem}><Field label="Lista"><select name="listId" required>{data.referenceLists.map(list => <option key={list.id} value={list.id}>{list.label}</option>)}</select></Field><Field label="Valor interno"><input name="value" required placeholder="Ex.: DISPENSA" /></Field><Field label="Rótulo exibido" full><input name="label" required placeholder="Ex.: Dispensa de licitação" /></Field><Field label="Ordem"><input name="sortOrder" type="number" min="0" defaultValue="0" /></Field><Field label="Situação" full><label className="checkbox-line"><input type="checkbox" name="active" defaultChecked /> Item ativo</label></Field><button className="button button-ink button-sm" type="submit" disabled={saveReferenceListItem.isPending}>Salvar item <Check size={15} /></button></form> : <p className="task-empty">Crie uma lista antes de adicionar itens.</p>}</article></section>
  </AppShell>;
}

function PrivacyPage({ go, selectedProcessId, selectProcess }: { go: (screen: Exclude<Screen, "landing">) => void; selectedProcessId: string | null; selectProcess: (id: string) => void }) {
  const utils = trpc.useUtils();
  const processList = trpc.procurement.list.useQuery();
  const [processId, setProcessId] = useState(selectedProcessId ?? "");
  const planningBoard = trpc.planning.board.useQuery();
  const board = { ...planningBoard, data: planningBoard.data ? { ...planningBoard.data, consolidations: planningBoard.data.pcas } : undefined };
  const [attachmentTarget, setAttachmentTarget] = useState("");
  useEffect(() => { if (selectedProcessId) setProcessId(selectedProcessId); }, [selectedProcessId]);
  const assessment = trpc.privacy.assessment.useQuery({ processPublicId: processId || "" }, { enabled: Boolean(processId) });
  const save = trpc.privacy.save.useMutation({ onSuccess: () => { utils.privacy.assessment.invalidate({ processPublicId: processId }); utils.dashboard.summary.invalidate(); } });
  const addRisk = trpc.privacy.addRisk.useMutation({ onSuccess: () => utils.privacy.assessment.invalidate({ processPublicId: processId }) });
  const decide = trpc.privacy.decide.useMutation({ onSuccess: () => { utils.privacy.assessment.invalidate({ processPublicId: processId }); utils.dashboard.summary.invalidate(); } });
  const uploadPlanningDocument = trpc.planning.uploadDocument.useMutation({ onSuccess: () => utils.planning.board.invalidate() });
  const attachPlanningFile = (entityType: "demand" | "demand_consolidation" | "pca" | "consolidation" | "opening_request", entityPublicId: string, file: File | undefined) => {
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) { window.alert("O documento ultrapassa o limite de 8 MB."); return; }
    const reader = new FileReader();
    reader.onload = () => uploadPlanningDocument.mutate({ entityType, entityPublicId, documentType: entityType === "demand" ? "Anexo da DFD" : entityType === "demand_consolidation" ? "Anexo da consolidação" : entityType === "pca" || entityType === "consolidation" ? "Documento do PCA" : "Anexo da solicitação de abertura", title: file.name, fileName: file.name, mimeType: file.type || "application/octet-stream", base64: String(reader.result ?? "") });
    reader.readAsDataURL(file);
  };
  const submitAssessment = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    save.mutate({
      processPublicId: processId,
      containsPersonalData: form.get("containsPersonalData") === "on",
      containsSensitiveData: form.get("containsSensitiveData") === "on",
      containsVulnerableData: form.get("containsVulnerableData") === "on",
      largeScale: form.get("largeScale") === "on",
      publicAreaMonitoring: form.get("publicAreaMonitoring") === "on",
      solelyAutomatedDecision: form.get("solelyAutomatedDecision") === "on",
      externalSharing: form.get("externalSharing") === "on",
      internationalTransfer: form.get("internationalTransfer") === "on",
      treatmentDescription: String(form.get("treatmentDescription") ?? "") || undefined,
      dataCategories: String(form.get("dataCategories") ?? "") || undefined,
      dataSubjectCategories: String(form.get("dataSubjectCategories") ?? "") || undefined,
      dataSource: String(form.get("dataSource") ?? "") || undefined,
      purpose: String(form.get("purpose") ?? "") || undefined,
      legalBasis: String(form.get("legalBasis") ?? "") || undefined,
      necessityAssessment: String(form.get("necessityAssessment") ?? "") || undefined,
      retentionPolicy: String(form.get("retentionPolicy") ?? "") || undefined,
      disposalMethod: String(form.get("disposalMethod") ?? "") || undefined,
      securityMeasures: String(form.get("securityMeasures") ?? "") || undefined,
      riskLevel: String(form.get("riskLevel")) as "unknown" | "low" | "medium" | "high",
      dpoConsulted: form.get("dpoConsulted") === "on",
      dpoOpinion: String(form.get("dpoOpinion") ?? "") || undefined,
    });
  };
  const submitRisk = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    addRisk.mutate({ processPublicId: processId, title: String(form.get("title") ?? ""), description: String(form.get("description") ?? "") || undefined, probability: String(form.get("probability")) as "low" | "medium" | "high", impact: String(form.get("impact")) as "low" | "medium" | "high", residualRisk: String(form.get("residualRisk")) as "low" | "medium" | "high", mitigation: String(form.get("mitigation") ?? "") || undefined, ownerRole: String(form.get("ownerRole") ?? "") || undefined });
  };
  const submitDecision = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    decide.mutate({ processPublicId: processId, outcome: String(form.get("outcome")) as "approved" | "needs_changes" | "risk_accepted" | "not_applicable", justification: String(form.get("justification") ?? "") });
  };
  const current = assessment.data;
  const item = current?.assessment;
  return <AppShell active="privacidade" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Privacidade" title="PRIVACIDADE — Análise LGPD" subtitle="Inventário, necessidade, riscos, controles e decisão humana por processo de contratação." actions={processId ? <button className="button button-ghost button-sm" onClick={() => { selectProcess(processId); go("trilha"); }}><Target size={15} /> Abrir TRILHA</button> : undefined} />
    <section className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">PROCESSO EM ANÁLISE</span><h2>Selecione o contexto</h2></div><ShieldCheck size={20} /></div><select value={processId} onChange={event => setProcessId(event.target.value)}><option value="">Selecione um processo registrado</option>{processList.data?.map(process => <option key={process.publicId} value={process.publicId}>{process.publicId} · {process.title}</option>)}</select>{processList.error ? <p className="form-error">{processList.error.message}</p> : null}</section>
    {!processId ? <EmptyState icon={<ShieldCheck size={30} />} title="A análise começa no processo" text="Selecione um processo para registrar o inventário de tratamento e organizar a revisão de compatibilidade com a LGPD." action={<button className="button button-ink button-sm" onClick={() => go("mapa")}><Search size={15} /> Consultar processos</button>} /> : assessment.isLoading ? <LoadingPanel message="Carregando análise LGPD…" /> : assessment.error ? <EmptyState icon={<AlertTriangle size={30} />} title="Revisão de privacidade restrita" text={assessment.error.message} /> : <>
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">TRIAGEM CONFIGURÁVEL</span><h2>Resultado atual</h2></div><Status tone={item?.riskLevel === "high" ? "danger" : item?.riskLevel === "medium" ? "warning" : "info"}>{item ? `Risco ${friendlyStatus(item.riskLevel).text}` : "Ainda não avaliado"}</Status></div><p className="trilha-current-copy">A ÓRBITA sinaliza pontos de atenção, mas não emite parecer jurídico automático nem decide a licitude do tratamento.</p><div className="checklist-box"><div className="checklist-row"><span className="check-circle">{current?.signals?.requiresReinforcedReview ? <AlertTriangle size={15} /> : <Check size={15} />}</span><div><strong>Revisão reforçada</strong><small>{current?.signals?.requiresReinforcedReview ? "Há fatores que exigem revisão humana pelo jurídico ou encarregado." : "Nenhum fator reforçado foi identificado na configuração atual."}</small></div></div><div className="checklist-row"><span className="check-circle">{current?.signals?.ripdRecommended ? <AlertTriangle size={15} /> : <Check size={15} />}</span><div><strong>Indicação de RIPD</strong><small>{current?.signals?.ripdRecommended ? "A combinação registrada recomenda avaliar a elaboração de RIPD." : "A triagem atual não gera recomendação automática de RIPD."}</small></div></div><div className="checklist-row"><span className="check-circle"><FileCheck2 size={15} /></span><div><strong>Decisão registrada</strong><small>{item?.status === "approved" ? "Aprovação humana registrada." : item?.status === "needs_changes" ? "Há correções pendentes." : "Nenhuma conclusão final foi registrada."}</small></div></div></div></article>
        <article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">HISTÓRICO</span><h2>Riscos e decisões</h2></div><ListChecks size={20} /></div>{current?.risks.length ? <div className="checklist-box">{current.risks.map(risk => <div className="checklist-row" key={risk.id}><span className="check-circle"><AlertTriangle size={14} /></span><div><strong>{risk.title}</strong><small>{`Probabilidade ${friendlyStatus(risk.probability).text} · Impacto ${friendlyStatus(risk.impact).text} · Residual ${friendlyStatus(risk.residualRisk).text}`}{risk.mitigation ? ` · Mitigação: ${risk.mitigation}` : ""}</small></div><Status tone={risk.residualRisk === "high" ? "danger" : risk.residualRisk === "medium" ? "warning" : "success"}>{friendlyStatus(risk.status).text}</Status></div>)}</div> : <p className="task-empty">Nenhum risco foi registrado nesta análise.</p>}{current?.decisions.length ? <div className="checklist-box">{current.decisions.map(decision => <div className="checklist-row" key={decision.id}><span className="check-circle check-circle-done"><Check size={14} /></span><div><strong>{friendlyStatus(decision.outcome).text}</strong><small>{decision.justification}</small></div></div>)}</div> : null}</article></section>
      <form key={`${processId}-${item?.id ?? "new"}`} className="form-stack" onSubmit={submitAssessment}><FormPanel title="Inventário do tratamento" help="Registre somente o que é necessário para a análise e mantenha a descrição vinculada ao objeto contratado."><Field label="Descrição do tratamento" full><textarea name="treatmentDescription" defaultValue={item?.treatmentDescription ?? ""} placeholder="Do recebimento de dados até o descarte, descreva as operações previstas." /></Field><Field label="Categorias de dados" full><textarea name="dataCategories" defaultValue={item?.dataCategories ?? ""} placeholder="Ex.: dados cadastrais, dados de contato, documentos de identificação." /></Field><Field label="Categorias de titulares"><textarea name="dataSubjectCategories" defaultValue={item?.dataSubjectCategories ?? ""} placeholder="Ex.: servidores, representantes de fornecedores, usuários." /></Field><Field label="Fonte dos dados"><textarea name="dataSource" defaultValue={item?.dataSource ?? ""} placeholder="Ex.: formulários, sistemas institucionais, fornecedor." /></Field><Field label="Finalidade específica" full><textarea name="purpose" defaultValue={item?.purpose ?? ""} placeholder="Explique a finalidade relacionada à contratação e à execução contratual." /></Field><Field label="Hipótese legal indicada"><input name="legalBasis" defaultValue={item?.legalBasis ?? ""} placeholder="A ser validada pelo jurídico/encarregado" /></Field><Field label="Necessidade e proporcionalidade" full><textarea name="necessityAssessment" defaultValue={item?.necessityAssessment ?? ""} placeholder="Justifique por que os dados são pertinentes, proporcionais e não excessivos." /></Field></FormPanel>
        <FormPanel title="Risco, retenção e salvaguardas" help="Os marcadores acionam alertas de revisão; eles não substituem a análise jurídica ou do encarregado."><Field label="Risco geral"><select name="riskLevel" defaultValue={item?.riskLevel ?? "unknown"}><option value="unknown">Ainda não classificado</option><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option></select></Field><Field label="Retenção e descarte"><textarea name="retentionPolicy" defaultValue={item?.retentionPolicy ?? ""} placeholder="Prazo de guarda, regra de eliminação ou arquivamento." /></Field><Field label="Método de descarte"><textarea name="disposalMethod" defaultValue={item?.disposalMethod ?? ""} placeholder="Descreva descarte, anonimização ou retenção legal." /></Field><Field label="Medidas de segurança" full><textarea name="securityMeasures" defaultValue={item?.securityMeasures ?? ""} placeholder="Controles de acesso, registro de eventos, criptografia, backups ou outros controles aplicáveis." /></Field><Field label="Fatores de atenção" full><div className="checklist-box"><label className="checkbox-line"><input type="checkbox" name="containsPersonalData" defaultChecked={item?.containsPersonalData} /> Trata dados pessoais</label><label className="checkbox-line"><input type="checkbox" name="containsSensitiveData" defaultChecked={item?.containsSensitiveData} /> Trata dados pessoais sensíveis</label><label className="checkbox-line"><input type="checkbox" name="containsVulnerableData" defaultChecked={item?.containsVulnerableData} /> Envolve crianças, adolescentes, idosos ou outro público vulnerável</label><label className="checkbox-line"><input type="checkbox" name="largeScale" defaultChecked={item?.largeScale} /> Pode envolver larga escala</label><label className="checkbox-line"><input type="checkbox" name="publicAreaMonitoring" defaultChecked={item?.publicAreaMonitoring} /> Envolve monitoramento de área acessível ao público</label><label className="checkbox-line"><input type="checkbox" name="solelyAutomatedDecision" defaultChecked={item?.solelyAutomatedDecision} /> Há decisão exclusivamente automatizada</label><label className="checkbox-line"><input type="checkbox" name="externalSharing" defaultChecked={item?.externalSharing} /> Prevê compartilhamento externo</label><label className="checkbox-line"><input type="checkbox" name="internationalTransfer" defaultChecked={item?.internationalTransfer} /> Prevê transferência internacional</label></div></Field><Field label="Consulta ao encarregado" full><label className="checkbox-line"><input type="checkbox" name="dpoConsulted" defaultChecked={item?.dpoConsulted} /> O encarregado/DPO foi consultado</label><textarea name="dpoOpinion" defaultValue={item?.dpoOpinion ?? ""} placeholder="Registre a orientação, ressalva ou encaminhamento do encarregado." /></Field></FormPanel>{save.error ? <p className="form-error">{save.error.message}</p> : null}<div className="form-footer"><span className="task-empty">Salvar atualiza a análise e preserva a memória; não gera decisão jurídica automática.</span><button className="button button-ink" type="submit" disabled={save.isPending}>{save.isPending ? "Salvando…" : "Salvar análise LGPD"} <ShieldCheck size={16} /></button></div></form>
      {item ? <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">RISCOS</span><h2>Adicionar risco e mitigação</h2></div><AlertTriangle size={20} /></div><form className="form-stack" onSubmit={submitRisk}><Field label="Risco identificado"><input name="title" minLength={3} required placeholder="Ex.: acesso indevido a dados cadastrais" /></Field><Field label="Probabilidade"><select name="probability"><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option></select></Field><Field label="Impacto"><select name="impact"><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option></select></Field><Field label="Risco residual"><select name="residualRisk"><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option></select></Field><Field label="Descrição" full><textarea name="description" placeholder="Descreva a consequência potencial para os titulares." /></Field><Field label="Medida de mitigação" full><textarea name="mitigation" placeholder="Descreva a salvaguarda, controle ou ação necessária." /></Field><Field label="Responsável pela medida"><input name="ownerRole" placeholder="Ex.: Encarregado LGPD, Compras ou TI" /></Field>{addRisk.error ? <p className="form-error">{addRisk.error.message}</p> : null}<button className="button button-ghost button-sm" type="submit" disabled={addRisk.isPending}><Plus size={15} /> Registrar risco</button></form></article><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">DECISÃO HUMANA</span><h2>Registrar conclusão</h2></div><FileCheck2 size={20} /></div><p className="trilha-current-copy">A conclusão deve ser emitida pela pessoa institucional responsável. A ÓRBITA só registra a motivação e a vincula ao processo.</p><form className="form-stack" onSubmit={submitDecision}><Field label="Resultado"><select name="outcome"><option value="approved">Aprovar com as salvaguardas registradas</option><option value="needs_changes">Solicitar adequações</option><option value="risk_accepted">Aceitar risco com motivação</option><option value="not_applicable">Registrar não aplicabilidade</option></select></Field><Field label="Justificativa" full><textarea name="justification" minLength={10} required placeholder="Registre a fundamentação, as condições e os encaminhamentos da decisão." /></Field>{decide.error ? <p className="form-error">{decide.error.message}</p> : null}<button className="button button-ink button-sm" type="submit" disabled={decide.isPending}>{decide.isPending ? "Registrando…" : "Registrar decisão"} <FileCheck2 size={15} /></button></form></article></section> : null}
      <section className="content-two-columns"><article className="surface-panel"><div className="panel-heading"><div><span className="panel-kicker">DOCUMENTOS TRANSVERSAIS</span><h2>Anexos de planejamento</h2></div><Paperclip size={20} /></div><select value={attachmentTarget} onChange={event => setAttachmentTarget(event.target.value)}><option value="">Selecione DFD, PCA ou solicitação</option>{board.data?.demands.map(row => <option key={`d-${row.demand.id}`} value={`demand:${row.demand.publicId}`}>DFD · {row.demand.publicId} · {row.demand.title}</option>)}{board.data?.consolidations.map(pca => <option key={`p-${pca.id}`} value={`consolidation:${pca.publicId}`}>PCA · {pca.publicId} · {pca.title}</option>)}{board.data?.openingRequests.map(item => <option key={`a-${item.request.id}`} value={`opening_request:${item.request.publicId}`}>Abertura · {item.request.publicId} · {item.demandTitle}</option>)}</select><label className="upload-zone compact-upload"><Upload size={20} /><strong>{uploadPlanningDocument.isPending ? "Enviando documento…" : "Anexar documento"}</strong><span>PDF, XLSX, DOCX ou imagem · máximo de 8 MB</span><input type="file" disabled={!attachmentTarget || uploadPlanningDocument.isPending} onChange={event => { const [entityType, entityPublicId] = attachmentTarget.split(":"); if (["demand", "consolidation", "opening_request"].includes(entityType) && entityPublicId) attachPlanningFile(entityType as "demand" | "consolidation" | "opening_request", entityPublicId, event.target.files?.[0]); }} /></label>{uploadPlanningDocument.error ? <p className="form-error">{uploadPlanningDocument.error.message}</p> : null}<div className="file-list">{board.data?.documents.length ? board.data.documents.slice(0, 8).map(document => <a className="file-row" key={document.id} href={document.storageUrl} target="_blank" rel="noreferrer"><span className="file-icon"><FileText size={17} /></span><strong>{document.title}</strong><small>{document.entityType} · {document.documentType} · v{document.version}</small></a>) : <p className="task-empty">Nenhum documento de planejamento anexado.</p>}</div></article>
        <article className="surface-panel alert-panel"><div className="panel-heading"><div><span className="panel-kicker">FAROL</span><h2>Alertas do planejamento</h2></div><Bell size={20} /></div>{board.data?.alerts.length ? board.data.alerts.map(alert => <AlertItem key={alert.id} code={alert.entityType === "demand" ? "DFD" : alert.entityType === "consolidation" ? "PCA" : "Abertura"} message={alert.title} tone={alert.severity === "critical" ? "danger" : alert.severity === "warning" ? "warning" : "info"} />) : <EmptyState icon={<ShieldCheck size={26} />} title="Nenhum alerta aberto" text="As pendências de DFD, PCA e abertura serão exibidas aqui." />}</article></section>
    </>}</AppShell>;
}

function ModalitiesPage({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const utils = trpc.useUtils();
  const overview = trpc.administration.overview.useQuery();
  const saveList = trpc.administration.saveReferenceList.useMutation({ onSuccess: () => utils.administration.overview.invalidate() });
  const saveItem = trpc.administration.saveReferenceListItem.useMutation({ onSuccess: () => utils.administration.overview.invalidate() });
  const list = overview.data?.referenceLists.find(item => item.code === "MODALIDADES_CONTRATACAO");
  const submitList = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); saveList.mutate({ code: "MODALIDADES_CONTRATACAO", label: String(form.get("label") ?? "Modalidades de contratação"), description: String(form.get("description") ?? "") || undefined, active: form.get("active") === "on" }); };
  const submitItem = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!list) return; const form = new FormData(event.currentTarget); const label = String(form.get("label") ?? "").trim(); const value = label.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_|_$/g, ""); saveItem.mutate({ listId: list.id, value, label, sortOrder: Number(form.get("sortOrder")) || 0, active: form.get("active") === "on" }); };
  return <AppShell active="modalidades" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Catálogos" title="MODALIDADES — Catálogo institucional" subtitle="Administre as opções utilizadas por Compras ao solicitar a abertura do processo, sem fixá-las no código da plataforma." actions={<button className="button button-ghost button-sm" onClick={() => go("agenda")}><CalendarDays size={15} /> Abrir AGENDA</button>} />
    <section className="catalog-hero glass-panel"><div><span className="panel-kicker">LISTA VINCULADA À ABERTURA</span><h2>Modalidades de contratação</h2><p>Os itens ativos aparecem no pedido de abertura após a publicação do PCA. A Presidência continua responsável pela autorização humana da abertura e da modalidade.</p></div><div className="catalog-orbit"><ListFilter size={28} /><strong>{list?.items.length ?? 0}</strong><small>itens ativos</small></div></section>
    {overview.isLoading ? <LoadingPanel message="Carregando o catálogo institucional…" /> : overview.error ? <EmptyState icon={<AlertTriangle size={28} />} title="Catálogo indisponível" text={overview.error.message} /> : <section className="catalog-layout"><article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">CONFIGURAÇÃO</span><h2>Definir a lista</h2></div><SlidersHorizontal size={20} /></div><form className="form-stack" onSubmit={submitList}><Field label="Nome da lista" full><input name="label" required defaultValue={list?.label ?? "Modalidades de contratação"} /></Field><Field label="Orientação de uso" full><textarea name="description" defaultValue={list?.description ?? ""} placeholder="Explique quem administra a lista e em qual fase ela será utilizada." /></Field><Field label="Situação" full><label className="checkbox-line"><input name="active" type="checkbox" defaultChecked={list?.active ?? true} /> Lista ativa para solicitações de abertura</label></Field>{saveList.error ? <p className="form-error">{saveList.error.message}</p> : null}<button className="button button-ink" type="submit" disabled={saveList.isPending}>{saveList.isPending ? "Salvando…" : list ? "Atualizar lista" : "Criar lista institucional"} <Check size={16} /></button></form></article>
      <article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">NOVO ITEM</span><h2>Adicionar modalidade</h2></div><Plus size={20} /></div>{list ? <form className="form-stack" onSubmit={submitItem}><Field label="Nome da modalidade" full><input name="label" required placeholder="Ex.: Dispensa de licitação" /></Field><Field label="Ordem de exibição"><input name="sortOrder" type="number" min="0" defaultValue={(list.items.length + 1) * 10} /></Field><Field label="Situação" full><label className="checkbox-line"><input name="active" type="checkbox" defaultChecked /> Item ativo</label></Field>{saveItem.error ? <p className="form-error">{saveItem.error.message}</p> : null}<button className="button button-cyan" type="submit" disabled={saveItem.isPending}>{saveItem.isPending ? "Salvando…" : "Adicionar modalidade"} <Plus size={16} /></button></form> : <EmptyState icon={<ListFilter size={28} />} title="Crie o catálogo primeiro" text="Defina a lista institucional ao lado antes de adicionar modalidades." />}</article></section>}
    <section className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">CATÁLOGO VIGENTE</span><h2>Itens cadastrados</h2></div><Status tone={list?.active ? "success" : "neutral"}>{list?.active ? "Lista ativa" : "Sem lista ativa"}</Status></div>{list?.items.length ? <div className="catalog-items">{list.items.map(item => <article className="catalog-item" key={item.id}><span className="catalog-order">{String(item.sortOrder).padStart(2, "0")}</span><div><strong>{item.label}</strong><small>Disponível para solicitação de abertura</small></div><Status tone={item.active ? "success" : "neutral"}>{item.active ? "Disponível" : "Inativo"}</Status></article>)}</div> : <EmptyState icon={<Boxes size={28} />} title="Nenhuma modalidade cadastrada" text="Inclua somente modalidades aprovadas pela norma e pela governança institucional." />}</section>
  </AppShell>;
}

function OficinaPage({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const utils = trpc.useUtils();
  const overview = trpc.administration.overview.useQuery();
  const signatureRequests = trpc.signature.list.useQuery();
  const eligibleSignatureDocuments = trpc.signature.eligibleDocuments.useQuery();
  const saveTemplate = trpc.administration.saveTemplate.useMutation({ onSuccess: () => utils.administration.overview.invalidate() });
  const prepareSignature = trpc.signature.prepareGovbr.useMutation({ onSuccess: () => utils.signature.list.invalidate() });
  const googleDrive = trpc.googleDrive.connection.useQuery();
  const beginGoogleDrive = trpc.googleDrive.beginAuthorization.useMutation({ onSuccess: data => { window.location.assign(data.authorizationUrl); } });
  const setGoogleDriveFolder = trpc.googleDrive.setRootFolder.useMutation({ onSuccess: () => googleDrive.refetch() });
  const disconnectGoogleDrive = trpc.googleDrive.disconnect.useMutation({ onSuccess: () => googleDrive.refetch() });
  const [kind, setKind] = useState("DOCUMENTO_GERAL");
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const title = String(form.get("title") ?? "").trim(); const documentType = String(form.get("documentType") ?? ""); const code = `${documentType}_${title}`.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_|_$/g, "").slice(0, 100); saveTemplate.mutate({ code, title, documentType, content: String(form.get("content") ?? "") || undefined, active: form.get("active") === "on" }); };
  const submitGoogleDriveFolder = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setGoogleDriveFolder.mutate({ folder: String(form.get("folder") ?? "") }); };
  const linkGoogleDriveTemplate = (event: FormEvent<HTMLFormElement>, template: NonNullable<typeof overview.data>["templates"][number]) => { event.preventDefault(); const form = new FormData(event.currentTarget); saveTemplate.mutate({ code: template.code, title: template.title, documentType: template.documentType, templateKind: "document", workflowStepKey: template.workflowStepKey ?? undefined, officialSourceUrl: template.officialSourceUrl ?? undefined, externalTemplateId: String(form.get("externalTemplate") ?? "").trim(), content: template.content ?? undefined, active: template.active }); };
  const driveTemplates = overview.data?.templates.filter(template => template.templateKind === "document") ?? [];
  const typeLabel: Record<string, string> = {
    DOCUMENTO_GERAL: "Documento institucional",
    CHECKLIST_DFD: "Checklist de DFD",
    CHECKLIST_PCA: "Checklist de PCA",
    CHECKLIST_ABERTURA: "Checklist de abertura",
    CHECKLIST_OFICIAL_CONTRATACAO_DIRETA: "Lista de verificação oficial",
    ETP: "Modelo gerador de ETP",
    TR: "Modelo gerador de TR",
    RPP: "Modelo gerador de RPP",
    EDITAL: "Modelo gerador de edital",
  };
  return <AppShell active="oficina" go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow="Governança / Oficina" title="OFICINA — Modelos e controles" subtitle="Crie versões de documentos e checklists. Modelos ativos de checklist são aplicados às fases correspondentes do planejamento." actions={<button className="button button-ghost button-sm" onClick={() => go("agenda")}><ListChecks size={15} /> Ver checklists aplicados</button>} />
    <section className="oficina-intro glass-panel"><div className="oficina-symbol"><Wrench size={25} /></div><div><span className="panel-kicker">BIBLIOTECA CONTROLADA</span><h2>Do conteúdo-modelo ao controle do fluxo.</h2><p>Documentos ficam versionados. Checklists usam uma linha por item e são instanciados quando a DFD, o PCA ou a solicitação de abertura é criada.</p></div></section>
    <section className="catalog-layout"><article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">NOVO MODELO</span><h2>Redigir e versionar</h2></div><LayoutTemplate size={20} /></div><form className="form-stack" onSubmit={submit}><Field label="Tipo"><select name="documentType" value={kind} onChange={event => setKind(event.target.value)}><option value="DOCUMENTO_GERAL">Documento ou orientação</option><option value="CHECKLIST_DFD">Checklist da DFD</option><option value="CHECKLIST_PCA">Checklist do PCA</option><option value="CHECKLIST_ABERTURA">Checklist da abertura</option></select></Field><Field label="Título" full><input name="title" required placeholder="Nome institucional do modelo" /></Field><Field label={kind === "DOCUMENTO_GERAL" ? "Conteúdo ou orientação" : "Itens do checklist"} full><textarea name="content" placeholder={kind === "DOCUMENTO_GERAL" ? "Estrutura, instruções ou texto-base do documento." : "Um item por linha. Cada linha será aplicada como um controle."} /></Field><Field label="Situação" full><label className="checkbox-line"><input name="active" type="checkbox" defaultChecked /> Versão ativa</label></Field>{saveTemplate.error ? <p className="form-error">{saveTemplate.error.message}</p> : null}<button className="button button-ink" type="submit" disabled={saveTemplate.isPending}>{saveTemplate.isPending ? "Salvando…" : "Salvar nova versão"} <FileCheck2 size={16} /></button></form></article>
      <article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">COMO FUNCIONA</span><h2>Aplicação por fase</h2></div><Sparkles size={20} /></div><div className="template-guide"><div><span>01</span><strong>DFD</strong><small>O checklist da DFD é aplicado ao formalizar a demanda.</small></div><div><span>02</span><strong>PCA</strong><small>O checklist do PCA acompanha a consolidação administrativa.</small></div><div><span>03</span><strong>Abertura</strong><small>O checklist de abertura é aplicado antes da decisão presidencial.</small></div><div><span>04</span><strong>Documento</strong><small>Modelos gerais preservam orientações e versões institucionais.</small></div></div></article></section>
    <section className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">VERSÕES PUBLICADAS</span><h2>Biblioteca da OFICINA</h2></div><Status tone="info">{overview.data?.templates.length ?? 0} modelos</Status></div>{overview.isLoading ? <LoadingPanel message="Carregando modelos…" /> : overview.error ? <p className="form-error">{overview.error.message}</p> : overview.data?.templates.length ? <div className="template-library">{overview.data.templates.map(template => <article className="template-card" key={template.id}><div><span className="template-type">{typeLabel[template.documentType] ?? friendlyInternalLabel(template.documentType)}</span><strong>{template.title}</strong><small>Versão {template.version}{template.workflowStepKey ? ` · etapa ${friendlyInternalLabel(template.workflowStepKey)}` : ""}</small></div><Status tone={template.active ? "success" : "neutral"}>{template.active ? "Ativo" : "Inativo"}</Status><p>{template.content ? template.content.split(/\r?\n/).filter(Boolean).slice(0, 2).join(" · ") : "Modelo sem conteúdo registrado."}</p>{template.officialSourceUrl ? <a className="text-button" href={template.officialSourceUrl} target="_blank" rel="noreferrer">Consultar fonte oficial</a> : null}{template.templateKind === "document" && !template.externalTemplateId ? <small className="template-config-note">Aguardando vínculo do modelo editável no Google Drive.</small> : null}</article>)}</div> : <EmptyState icon={<LayoutTemplate size={28} />} title="A biblioteca está vazia" text="Crie o primeiro documento ou checklist para orientar as próximas fases." />}</section>
    <section className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">MODELOS EDITÁVEIS</span><h2>Vincular documentos do Google Drive</h2></div><FolderKanban size={20} /></div><p className="trilha-current-copy">Crie ou escolha no Google Drive o documento-base de cada tipo e cole abaixo o link. Ao gerar um arquivo pela TRILHA, a ÓRBITA cria uma cópia na pasta do processo e preenche os campos iniciais.</p>{driveTemplates.length ? <div className="template-library">{driveTemplates.map(template => <article className="template-card" key={`drive-${template.id}`}><div><span className="template-type">{typeLabel[template.documentType] ?? template.documentType}</span><strong>{template.title}</strong><small>{template.externalTemplateId ? "Modelo editável vinculado" : "Vínculo pendente"}</small></div><form className="form-stack" onSubmit={event => linkGoogleDriveTemplate(event, template)}><input name="externalTemplate" required defaultValue={template.externalTemplateId ?? ""} placeholder="Cole o link do documento-modelo no Google Drive" /><button className="button button-ghost button-sm" type="submit" disabled={saveTemplate.isPending}>{saveTemplate.isPending ? "Salvando…" : "Salvar vínculo"}</button></form></article>)}</div> : <p className="task-empty">Os modelos geradores ainda não estão disponíveis no catálogo.</p>}</section>
    <section className="content-two-columns"><article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">ARQUIVOS DE PROCESSO</span><h2>Google Drive pessoal</h2></div><FolderKanban size={20} /></div><p className="trilha-current-copy">A conta conectada é usada somente quando você criar um arquivo pelo processo. A ÓRBITA não utiliza Apps Script nem acessa o Drive sem sua autorização.</p>{googleDrive.isLoading ? <LoadingPanel message="Consultando conexão do Google Drive…" /> : googleDrive.data && !googleDrive.data.revokedAt ? <><div className="operational-list"><article><span className="operational-dot" /><div><strong>{googleDrive.data.googleEmail ?? "Conta Google conectada"}</strong><small>{googleDrive.data.rootFolderUrl ? "Pasta institucional definida" : "Defina a pasta institucional antes de criar o primeiro arquivo"}</small></div><Status tone="success">Conectado</Status></article></div><form className="inline-task-form" onSubmit={submitGoogleDriveFolder}><input name="folder" required defaultValue={googleDrive.data.rootFolderUrl ?? ""} placeholder="Cole o link da pasta institucional do Google Drive" /><button className="button button-ghost button-sm" type="submit" disabled={setGoogleDriveFolder.isPending}>{setGoogleDriveFolder.isPending ? "Salvando…" : "Salvar pasta"}</button></form><button className="text-button" type="button" disabled={disconnectGoogleDrive.isPending} onClick={() => disconnectGoogleDrive.mutate()}>{disconnectGoogleDrive.isPending ? "Desconectando…" : "Desconectar minha conta"}</button></> : <button className="button button-ink button-sm" type="button" disabled={beginGoogleDrive.isPending} onClick={() => beginGoogleDrive.mutate()}><FolderKanban size={15} />{beginGoogleDrive.isPending ? "Abrindo Google…" : "Conectar Google Drive"}</button>}{beginGoogleDrive.error ? <p className="form-error">{beginGoogleDrive.error.message}</p> : null}{setGoogleDriveFolder.error ? <p className="form-error">{setGoogleDriveFolder.error.message}</p> : null}</article>
      <article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">AUTENTICAÇÃO DOCUMENTAL</span><h2>Assinatura eletrônica gov.br</h2></div><Status tone="warning">Aguardando credenciais</Status></div><p className="trilha-current-copy">A trilha de assinatura já está preparada e registra solicitações em auditoria. A integração externa permanece desativada até o órgão cadastrar as credenciais, a URL de retorno e a homologação necessárias.</p>{eligibleSignatureDocuments.isLoading ? <LoadingPanel message="Carregando documentos elegíveis…" /> : eligibleSignatureDocuments.error ? <p className="form-error">Não foi possível consultar os documentos elegíveis para assinatura.</p> : [...(eligibleSignatureDocuments.data?.planning ?? []).map(document => ({ ...document, scope: "planning" as const, scopeLabel: "Documento de planejamento" })), ...(eligibleSignatureDocuments.data?.process ?? []).map(document => ({ ...document, scope: "process" as const, scopeLabel: "Documento do processo" }))].length ? <div className="operational-list">{[...(eligibleSignatureDocuments.data?.planning ?? []).map(document => ({ ...document, scope: "planning" as const, scopeLabel: "Documento de planejamento" })), ...(eligibleSignatureDocuments.data?.process ?? []).map(document => ({ ...document, scope: "process" as const, scopeLabel: "Documento do processo" }))].map(document => <article key={`${document.scope}-${document.id}`}><span className="operational-dot" /><div><strong>{document.title}</strong><small>{document.scopeLabel} · versão {document.version}</small></div><button className="button button-ghost button-sm" type="button" disabled={prepareSignature.isPending} onClick={() => prepareSignature.mutate({ documentScope: document.scope, documentId: document.id })}>{prepareSignature.isPending ? "Preparando…" : "Preparar assinatura"}</button></article>)}</div> : <EmptyState icon={<FileCheck2 size={28} />} title="Nenhum documento elegível" text="Quando houver documentos de planejamento ou de processo registrados, eles poderão ser preparados para assinatura sem envio externo." />}{prepareSignature.error ? <p className="form-error">{prepareSignature.error.message}</p> : null}{signatureRequests.isLoading ? <LoadingPanel message="Carregando solicitações de assinatura…" /> : signatureRequests.error ? <p className="form-error">Não foi possível consultar as solicitações de assinatura.</p> : signatureRequests.data?.length ? <div className="operational-list">{signatureRequests.data.map(request => <article key={request.id}><span className="operational-dot" /><div><strong>Solicitação de assinatura preparada</strong><small>{request.documentScope === "planning" ? "Documento de planejamento" : "Documento do processo"} · {formatDate(request.requestedAt)}</small></div><Status tone={friendlyStatus(request.status).tone}>{friendlyStatus(request.status).text}</Status></article>)}</div> : <p className="task-empty">Ainda não há solicitações de assinatura preparadas.</p>}</article></section>
  </AppShell>;
}

function FlowPanel({ go }: { go: (screen: Exclude<Screen, "landing">) => void }) {
  const board = trpc.planning.board.useQuery();
  const data = board.data ? { ...board.data, consolidations: board.data.pcas } : undefined;
  const flow = [
    { code: "01", title: "DFD", role: "Setor requisitante", detail: "Demanda formalizada e triagem LGPD", count: data?.demands.filter(row => ["submitted", "under_review"].includes(row.demand.status)).length ?? 0, screen: "porta" as const, icon: FileText },
    { code: "02", title: "Consolidação", role: "Diretoria de Administração", detail: "Agrupamento de DFDs semelhantes", count: data?.demandConsolidations.filter(row => row.status === "ready_for_pca").length ?? 0, screen: "agenda" as const, icon: Layers },
    { code: "03", title: "PCA único", role: "Diretoria de Administração", detail: "Documento formado a partir das consolidações", count: data?.pcas.filter(row => ["draft", "ready_for_review", "returned"].includes(row.status)).length ?? 0, screen: "agenda" as const, icon: Boxes },
    { code: "04", title: "Deliberação", role: "Presidência", detail: "Aprovação, devolução ou rejeição motivada", count: data?.pcas.filter(row => row.status === "presidency_review").length ?? 0, screen: "agenda" as const, icon: Landmark },
    { code: "05", title: "Abertura", role: "Compras e Presidência", detail: "Modalidade proposta e autorização formal", count: data?.openingRequests.filter(row => row.request.status === "presidency_review").length ?? 0, screen: "agenda" as const, icon: ListFilter },
    { code: "06", title: "Instauração", role: "Setor de Compras", detail: "Processo liberado para a TRILHA", count: data?.openingRequests.filter(row => row.request.status === "authorized").length ?? 0, screen: "trilha" as const, icon: Target },
  ];
  return <AppShell active="fluxo" go={go} userName="" alertCount={data?.alerts.length ?? 0} logout={() => undefined}><PageHeading eyebrow="Planejamento / Acompanhamento" title="FLUXO — Da DFD à instauração" subtitle="Visualize a situação real de cada marco e acesse a área responsável sem reduzir as decisões humanas a automatismos." actions={<button className="button button-ink button-sm" onClick={() => go("agenda")}><CalendarDays size={15} /> Abrir AGENDA</button>} />
    {board.isLoading ? <LoadingPanel message="Lendo os marcos do planejamento…" /> : board.error ? <EmptyState icon={<AlertTriangle size={28} />} title="Fluxo indisponível" text={board.error.message} /> : <><section className="flow-overview glass-panel"><div><span className="panel-kicker">TRILHA INSTITUCIONAL</span><h2>O processo só nasce após autorização.</h2><p>O quadro acompanha DFD, PCA, deliberação e abertura como fases independentes. A instauração ocorre apenas quando a solicitação autorizada chega ao Setor de Compras.</p></div><div className="flow-summary"><strong>{data?.demands.length ?? 0}</strong><span>DFD no histórico</span><strong>{data?.consolidations.length ?? 0}</strong><span>PCA registrados</span></div></section><section className="flow-track">{flow.map((stage, index) => { const Icon = stage.icon; return <article className={`flow-stage ${stage.count ? "flow-stage-active" : ""}`} key={stage.code}><button type="button" onClick={() => go(stage.screen)}><span className="flow-stage-code">{stage.code}</span><span className="flow-stage-icon"><Icon size={19} /></span><span className="flow-stage-title"><strong>{stage.title}</strong><small>{stage.role}</small></span><span className="flow-stage-count">{stage.count}<small>em ação</small></span><ArrowRight size={17} /></button>{index < flow.length - 1 ? <i className="flow-connector" /> : null}<p>{stage.detail}</p></article>; })}</section><section className="content-two-columns"><article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">ATENÇÃO OPERACIONAL</span><h2>Alertas da jornada</h2></div><Bell size={20} /></div>{data?.alerts.length ? data.alerts.slice(0, 6).map(alert => <AlertItem key={alert.id} code={alert.entityType === "demand" ? "DFD" : alert.entityType === "consolidation" ? "PCA" : "Abertura"} message={alert.title} tone={alert.severity === "critical" ? "danger" : alert.severity === "warning" ? "warning" : "info"} />) : <EmptyState icon={<ShieldCheck size={28} />} title="Jornada sem alertas" text="Os prazos e pendências aparecerão aqui conforme as fases forem movimentadas." />}</article><article className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">ATOS INSTITUCIONAIS</span><h2>Próximas ações</h2></div><ClipboardList size={20} /></div><div className="flow-actions"><button onClick={() => go("porta")}><FileText size={17} /><span><strong>Formalizar DFD</strong><small>Inicie a demanda sem definir modalidade.</small></span><ArrowRight size={15} /></button><button onClick={() => go("oficina")}><LayoutTemplate size={17} /><span><strong>Preparar controles</strong><small>Atualize modelos e checklists da OFICINA.</small></span><ArrowRight size={15} /></button><button onClick={() => go("modalidades")}><ListFilter size={17} /><span><strong>Revisar modalidades</strong><small>Configure o catálogo para a fase de abertura.</small></span><ArrowRight size={15} /></button></div></article></section></>}
  </AppShell>;
}

function ModulePlaceholder({ go, screen, eyebrow, title, description, icon }: { go: (screen: Exclude<Screen, "landing">) => void; screen: Screen; eyebrow: string; title: string; description: string; icon: ReactNode }) {
  return <AppShell active={screen} go={go} userName="" alertCount={0} logout={() => undefined}><PageHeading eyebrow={eyebrow} title={title} subtitle={description} /><section className="module-placeholder glass-panel"><div className="placeholder-orbit">{icon}</div><div><span className="panel-kicker">MÓDULO EM PREPARAÇÃO</span><h2>Destino já conectado à navegação.</h2><p>Este núcleo está reservado para a próxima entrega. A estrutura visual, o acesso pelo menu e o contexto institucional já estão disponíveis sem simular registros administrativos.</p><div className="hero-actions"><button className="button button-ink" onClick={() => go("fluxo")}><GitBranch size={16} /> Ver fluxo institucional</button><button className="button button-ghost" onClick={() => go("dashboard")}><LayoutDashboard size={16} /> Voltar à ÁGUIA</button></div></div></section></AppShell>;
}

type OperationalScreen = "farol" | "memoria" | "lastro" | "maestro" | "eco" | "vitrine" | "elo" | "vigia" | "bussola";

function OperationalModulePage({ go, screen }: { go: (screen: Exclude<Screen, "landing">) => void; screen: OperationalScreen }) {
  const board = trpc.planning.board.useQuery();
  const dashboard = trpc.dashboard.summary.useQuery();
  const processes = trpc.procurement.list.useQuery();
  const config: Record<OperationalScreen, { eyebrow: string; title: string; subtitle: string; icon: ReactNode; action: Exclude<Screen, "landing">; actionLabel: string }> = {
    farol: { eyebrow: "Governança / Farol", title: "FAROL — Alertas institucionais", subtitle: "Atenção operacional para prazos, pendências e decisões que exigem ciência humana.", icon: <Bell size={24} />, action: "fluxo", actionLabel: "Ver fluxo" },
    memoria: { eyebrow: "Governança / Memória", title: "MEMÓRIA — Rastros de processo", subtitle: "Consulta aos processos registrados para acessar etapas, documentos e histórico auditável.", icon: <Archive size={24} />, action: "mapa", actionLabel: "Abrir MAPA" },
    lastro: { eyebrow: "Governança / Lastro", title: "LASTRO — Documentos vinculados", subtitle: "Acervo de documentos de DFD, PCA e solicitações de abertura, preservando versões e origem.", icon: <FileCog size={24} />, action: "agenda", actionLabel: "Abrir AGENDA" },
    maestro: { eyebrow: "Contratação / Maestro", title: "MAESTRO — Propostas e fornecedores", subtitle: "Acesso aos processos para registrar propostas de fornecedores ativos na etapa adequada da TRILHA.", icon: <PanelTop size={24} />, action: "trilha", actionLabel: "Abrir TRILHA" },
    eco: { eyebrow: "Contratação / ECO", title: "ECO — Publicações", subtitle: "Acompanhe PCA publicados, referências institucionais e documentos prontos para transparência.", icon: <Send size={24} />, action: "agenda", actionLabel: "Abrir AGENDA" },
    vitrine: { eyebrow: "Contratação / Vitrine", title: "VITRINE — Transparência", subtitle: "Visão organizada dos atos publicados e documentos associados para disponibilização institucional.", icon: <Eye size={24} />, action: "eco", actionLabel: "Ver publicações" },
    elo: { eyebrow: "Execução / ELO", title: "ELO — Carteira de processos", subtitle: "Painel de processos formalizados que formarão a base do ciclo contratual.", icon: <FolderKanban size={24} />, action: "trilha", actionLabel: "Abrir TRILHA" },
    vigia: { eyebrow: "Execução / Vigia", title: "VIGIA — Acompanhamento", subtitle: "Ponto de acompanhamento para a futura fiscalização, já conectado aos processos em curso.", icon: <ClipboardList size={24} />, action: "trilha", actionLabel: "Abrir TRILHA" },
    bussola: { eyebrow: "Visão / Bússola", title: "BÚSSOLA — Indicadores", subtitle: "Leitura consolidada de planejamento, privacidade, aberturas e processos para gestão institucional.", icon: <Radar size={24} />, action: "dashboard", actionLabel: "Abrir ÁGUIA" },
  };
  const current = config[screen];
  const rows = (() => {
    if (screen === "farol") return (dashboard.data?.alerts ?? []).map(alert => ({ key: `alert-${alert.id}`, title: alert.title, detail: alert.severity === "critical" ? "Alerta crítico" : alert.severity === "warning" ? "Requer atenção" : "Em acompanhamento", tone: alert.severity === "critical" ? "danger" as const : alert.severity === "warning" ? "warning" as const : "info" as const }));
    if (screen === "lastro") return (board.data?.documents ?? []).map(document => ({ key: `document-${document.id}`, title: document.title, detail: `${friendlyInternalLabel(document.entityType)} · ${friendlyInternalLabel(document.documentType)} · versão ${document.version}`, tone: "info" as const }));
    if (screen === "eco" || screen === "vitrine") return (board.data?.pcas ?? []).filter(item => item.status === "published").map(item => ({ key: item.publicId, title: item.title, detail: `${item.publicId} · ${item.publicationReference || "referência pendente"}`, tone: "success" as const }));
    if (screen === "bussola") return [
      { key: "demands", title: `${dashboard.data?.planning.demands ?? 0} DFD registradas`, detail: "Demandas na base institucional", tone: "info" as const },
      { key: "pca", title: `${dashboard.data?.planning.pcaAwaitingPresidency ?? 0} PCA na Presidência`, detail: "Deliberações em acompanhamento", tone: "warning" as const },
      { key: "privacy", title: `${dashboard.data?.planning.privacyInReview ?? 0} análises LGPD em revisão`, detail: "Triagem e decisão humana", tone: "info" as const },
      { key: "openings", title: `${dashboard.data?.planning.openingsAwaitingPresidency ?? 0} aberturas pendentes`, detail: "Pedidos aguardando autorização", tone: "warning" as const },
    ];
    return (processes.data ?? []).map(process => ({ key: process.publicId, title: `${process.publicId} · ${process.title}`, detail: "Processo disponível para consulta operacional", tone: "info" as const }));
  })();
  const waiting = board.isLoading || dashboard.isLoading || processes.isLoading;
  const failed = board.error ?? dashboard.error ?? processes.error;
  return <AppShell active={screen} go={go} userName="" alertCount={dashboard.data?.alerts.length ?? 0} logout={() => undefined}><PageHeading eyebrow={current.eyebrow} title={current.title} subtitle={current.subtitle} actions={<button className="button button-ink button-sm" onClick={() => go(current.action)}>{current.icon} {current.actionLabel}</button>} />
    <section className="operational-banner glass-panel"><span>{current.icon}</span><div><span className="panel-kicker">NÚCLEO OPERACIONAL</span><h2>Dados reais, sem registros simulados.</h2><p>Este módulo consolida informações já registradas nos fluxos disponíveis e direciona as ações para a área responsável.</p></div></section>
    {waiting ? <LoadingPanel message="Carregando informações operacionais…" /> : failed ? <EmptyState icon={<AlertTriangle size={28} />} title="Módulo indisponível" text={failed.message} /> : <section className="surface-panel glass-panel"><div className="panel-heading"><div><span className="panel-kicker">REGISTROS ATUAIS</span><h2>{rows.length} item(ns) disponível(is)</h2></div><Status tone={rows.length ? "info" : "neutral"}>{rows.length ? "Atualizado" : "Sem registros"}</Status></div>{rows.length ? <div className="operational-list">{rows.map(row => <article key={row.key}><span className="operational-dot" /><div><strong>{row.title}</strong><small>{row.detail}</small></div><Status tone={row.tone}>{row.tone === "danger" ? "Crítico" : row.tone === "warning" ? "Atenção" : row.tone === "success" ? "Publicado" : "Disponível"}</Status></article>)}</div> : <EmptyState icon={current.icon} title="Nenhum registro disponível" text="Quando o fluxo correspondente gerar registros, eles serão exibidos neste painel sem a criação automática de dados." action={<button className="button button-ink button-sm" onClick={() => go(current.action)}>{current.actionLabel} <ArrowRight size={15} /></button>} />}</section>}
  </AppShell>;
}

export default function Home() {
  const validScreens: Screen[] = ["landing", "dashboard", "porta", "trilha", "mapa", "agenda", "perfis", "privacidade", "administracao", "contas", "configuracoes", "modalidades", "oficina", "fluxo", "farol", "memoria", "maestro", "eco", "vitrine", "elo", "vigia", "bussola", "lastro", "oraculo", "ima"];
  const [screen, setScreen] = useState<Screen>(() => { const requested = window.location.hash.replace("#", "") as Screen; return validScreens.includes(requested) ? requested : "landing"; });
  const [selectedProcessId, setSelectedProcessId] = useState<string | null>(null);
  const { user, loading, isAuthenticated, logout } = useAuth();
  const workspace = trpc.workspace.status.useQuery(undefined, { enabled: isAuthenticated });
  const go = (next: Screen) => { setScreen(next); window.history.replaceState(null, "", next === "landing" ? window.location.pathname : `#${next}`); window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior }); };
  const selectAndOpen = (processId: string) => { setSelectedProcessId(processId); go("trilha"); };
  useEffect(() => { document.title = screen === "landing" ? "ÓRBITA · Plataforma Integrada de Contratações" : `ÓRBITA · ${screen.toUpperCase()}`; }, [screen]);
  useEffect(() => { const updateFromHash = () => { const requested = window.location.hash.replace("#", "") as Screen; setScreen(validScreens.includes(requested) ? requested : "landing"); }; window.addEventListener("hashchange", updateFromHash); return () => window.removeEventListener("hashchange", updateFromHash); }, []);
  if (screen === "landing") return <Landing authenticated={isAuthenticated} openWorkspace={() => go("dashboard")} openModule={go} />;
  if (loading) return <LoadingPanel message="Verificando sua sessão institucional…" />;
  if (!isAuthenticated) return <div className="login-page"><main className="login-main"><section className="login-intro" style={{ backgroundImage: `url(${ASSETS.darkSurface})` }}><div><div className="eyebrow eyebrow-light">Acesso protegido</div><h1>Uma trilha.<br />Responsabilidades claras.</h1><p>O ambiente operacional exige uma conta institucional para preservar autoria e rastreabilidade.</p></div></section><section className="login-form-panel"><div className="login-card"><BrandMark /><div className="eyebrow">Autenticação necessária</div><h2>Acessar a ÓRBITA</h2><p>Entre para consultar ou movimentar processos conforme suas permissões.</p><button className="button button-gov" onClick={startLogin}><ShieldCheck size={18} /> Entrar com conta institucional</button><button className="button button-ghost button-block" onClick={() => go("landing")}><ArrowLeft size={16} /> Voltar à página inicial</button><small><ShieldCheck size={14} /> As ações ficam vinculadas ao usuário autenticado.</small></div></section></main></div>;
  if (workspace.isLoading) return <LoadingPanel message="Preparando seu ambiente operacional…" />;
  if (workspace.error) return <LoadingPanel message="Não foi possível preparar o ambiente de trabalho." />;
  if (!workspace.data?.isConfigured) return <SetupWorkspace onReady={() => workspace.refetch()} />;
  const isInstitutionalAdmin = user?.role === "admin" || workspace.data.roles.includes("administrador");
  const activeProps = { userName: user?.name ?? "Usuário institucional", alertCount: 0, logout };
  if (screen === "dashboard") return <Dashboard go={go} selectProcess={selectAndOpen} />;
  if (screen === "porta") return <Porta go={go} units={workspace.data.units} afterCreate={() => go("agenda")} />;
  if (screen === "trilha") return <Trilha go={go} processId={selectedProcessId} />;
  if (screen === "mapa") return <MapaPage go={go} selectProcess={selectAndOpen} />;
  if (screen === "agenda") return <Agenda go={go} selectProcess={selectAndOpen} />;
  if (screen === "fluxo") return <FlowPanel go={go} />;
  if (screen === "privacidade") return <PrivacyPage go={go} selectedProcessId={selectedProcessId} selectProcess={setSelectedProcessId} />;
  if (screen === "administracao") return isInstitutionalAdmin ? <AdministrationPage go={go} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<ShieldCheck size={28} />} title="Acesso administrativo necessário" text="A configuração institucional está disponível apenas ao perfil administrador." /></AppShell>;
  if (screen === "contas") return isInstitutionalAdmin ? <LocalAccountsPage go={go} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<ShieldCheck size={28} />} title="Acesso administrativo necessário" text="A gestão de contas locais está disponível apenas ao perfil administrador." /></AppShell>;
  if (screen === "configuracoes") return <SettingsPage go={go} />;
  if (screen === "modalidades") return isInstitutionalAdmin ? <ModalitiesPage go={go} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<ShieldCheck size={28} />} title="Acesso administrativo necessário" text="O catálogo de modalidades é mantido pelo perfil administrador." /></AppShell>;
  if (screen === "oficina") return isInstitutionalAdmin ? <OficinaPage go={go} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<ShieldCheck size={28} />} title="Acesso administrativo necessário" text="Os modelos institucionais são mantidos pelo perfil administrador." /></AppShell>;
  if (screen === "ima") return isInstitutionalAdmin ? <AdministrationPage go={go} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<Users size={28} />} title="Acesso administrativo necessário" text="O diretório de fornecedores é mantido pelo perfil administrador." /></AppShell>;
  if (screen === "perfis") return isInstitutionalAdmin ? <ProfilesPage go={go} units={workspace.data.units} /> : <AppShell active="dashboard" go={go} {...activeProps}><EmptyState icon={<ShieldCheck size={28} />} title="Acesso administrativo necessário" text="A gestão de perfis está disponível apenas ao perfil administrador." /></AppShell>;
  if (screen === "oraculo") return <PrivacyPage go={go} selectedProcessId={selectedProcessId} selectProcess={setSelectedProcessId} />;
  const operationalScreens: OperationalScreen[] = ["farol", "memoria", "lastro", "maestro", "eco", "vitrine", "elo", "vigia", "bussola"];
  if (operationalScreens.includes(screen as OperationalScreen)) return <OperationalModulePage go={go} screen={screen as OperationalScreen} />;
  const placeholders: Record<string, { eyebrow: string; title: string; description: string; icon: ReactNode }> = {
  };
  if (screen in placeholders) { const item = placeholders[screen]; return <ModulePlaceholder go={go} screen={screen} {...item} />; }
  return <AppShell active="dashboard" go={go} {...activeProps}><LoadingPanel /></AppShell>;
}
